import {cloudAuthPage,cloudCheckout,cloudLegal,cloudAccount,cloudAdminOverview,cloudPayments} from './cloud-ui.js';
import {calculatePracticePlan,formatPlanTime,calculateIllustrativeScenario} from './planner.js';
const $=(s,r=document)=>r.querySelector(s);
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
const date=d=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(d));
const pct=v=>v==null?'—':`${Math.round(v)}%`;
const icon=(name,size=18)=>{const paths={arrow:'<path d="M7 17 17 7M7 7h10v10"/>',right:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 5v15M3 4c3-1 6 0 9 2 3-2 6-3 9-2v14c-3-1-6 0-9 2-3-2-6-3-9-2z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',flag:'<path d="M5 22V3c5-3 9 3 14 0v11c-5 3-9-3-14 0"/>',logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="m16 3 5 5L9 20l-6 1 1-6zM13 6l5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/>',wifi:'<path d="M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0M12 20h.01"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',infinity:'<path d="M12 12C8 5 3 6 3 12s5 7 9 0 9-6 9 0-5 7-9 0"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;};
const brand=()=>`<a class="brand" href="#/" aria-label="Simulou Passou — início"><span class="brand-stack"><span class="brand-word">Simulou <span>Passou</span></span><span class="brand-sub">simulador de provas</span></span></a>`;
const badge=(s,c='')=>`<span class="badge ${c}">${E(s)}</span>`;
const button=(label,action,opts='')=>data?.local===false&&action.startsWith('demo-')?`<a class="btn ${opts}" href="#/cadastro">Conhecer a plataforma</a>`:`<button class="btn ${opts}" data-action="${action}">${label}</button>`;
const link=(label,href,opts='')=>`<a class="btn ${opts}" href="${href}">${label}</a>`;
const bar=()=>data?.local===false?`<div class="local-bar"><span class="dot"></span>PRÉ-LANÇAMENTO · CONTEÚDO DEMONSTRATIVO · VENDAS AINDA NÃO HABILITADAS</div>`:`<div class="local-bar"><span class="dot"></span>PRÉVIA LOCAL · DADOS DE TESTE · SEM COBRANÇA REAL</div>`;
const notice=(text,kind='info')=>`<div class="alert ${kind}">${icon('info',17)}<div>${text}</div></div>`;
const empty=(title,description,cta='')=>`<div class="empty"><div class="empty-icon">${icon('book',22)}</div><h3>${title}</h3><p>${description}</p>${cta}</div>`;
const field=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${E(value)}" ${extra}></div>`;
const area=(name,label,value='',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${extra}>${E(value)}</textarea></div>`;
const select=(name,label,options,value)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,l])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(l)}</option>`).join('')}</select></div>`;
let data,adminData,currentAttempt,questionIndex=0,renderId=0,toastTimer,saveTimer,saving=false,dirty=false,saveProblem=false,finishBusy=false;
let lastFocus;
async function api(path,{method='GET',body}={}){const r=await fetch(new URL('api'+path,new URL('.',import.meta.url)),{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Não foi possível concluir.'),{status:r.status});return d;}
async function refresh(){data=await api('/bootstrap');}
function route(){const raw=(location.hash||'#/').slice(1);const [path,qs]=raw.split('?');return {path,parts:path.split('/').filter(Boolean),query:new URLSearchParams(qs||'')};}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const prepName=id=>data?.preparations.find(p=>p.id===id)?.name||'Preparação';
const prepOptions=()=>data.preparations.map(p=>[p.id,p.name]);
function statusBadge(a){return a.status==='in_progress'?badge('Em andamento','blue'):a.status==='awaiting_review'?badge('Aguardando correção'):a.result?.approved===true?badge('Meta alcançada','green'):a.result?.approved===false?badge('Em revisão','gray'):badge('Concluído','green');}
function errorPage(e){return `<div class="card">${empty('Não foi possível carregar',E(e.message),button('Tentar novamente','retry'))}</div>`;}
function header(){return `${bar()}<header class="public-header">${brand()}<nav class="public-nav" aria-label="Navegação principal"><a class="section-link" href="#como-funciona" data-scroll="como-funciona">Como funciona</a><a class="section-link" href="#incluido" data-scroll="incluido">O que está incluído</a><a href="${data.user?'#/inicio':'#/entrar'}">${data.user?'Minha área':'Já tenho acesso'}</a>${link('Quero meu acesso',data.user?.hasAccess?'#/inicio':'#/checkout','compact')}</nav></header>`;}
function landing() {
  const benefits = [
    ['list', 'Simulados por objetivo', 'Escolha uma prova ou certificação disponível e pratique com os simulados vinculados a ela.'],
    ['check', 'Revisão das respostas', 'Confira o que acertou, entenda os erros e retome os assuntos que merecem atenção.'],
    ['chart', 'Desempenho acompanhado', 'Consulte suas tentativas e compare seus resultados ao longo da prática.'],
    ['book', 'Materiais de apoio', 'Reforce os assuntos em que encontrou dificuldade com os materiais disponíveis.'],
  ];
  const faqs = [
    ['O que é o Simulou Passou?', 'É uma plataforma de simulação de provas. Você escolhe uma das provas ou certificações disponíveis, faz os simulados, revisa suas respostas e acompanha o desempenho. Os materiais de apoio ajudam a reforçar os assuntos.'],
    ['Quais provas e certificações estão disponíveis?', 'O catálogo mostra as opções efetivamente publicadas. Neste catálogo demonstrativo, ANCORD e PQO · Operações usam exemplos demonstrativos e distintos. Eles ainda não representam uma preparação completa, revisada ou o formato oficial dos exames.'],
    ['Preciso pagar todo mês?', 'Não. A oferta planejada é de R$ 29,90 em pagamento único, sem mensalidade ou renovação paga. Nesta prévia, não há cobrança.'],
    ['Preciso comprar cada certificação separadamente?', 'Não. Uma única compra libera todos os simulados e materiais disponibilizados nessa mesma oferta, incluindo novos conteúdos adicionados a ela.'],
    ['Posso repetir os simulados?', 'Sim, conforme as regras de cada simulado. Cada tentativa é registrada separadamente para você revisar e comparar seus resultados.'],
    ['Como funcionam a correção e a revisão?', 'Questões objetivas são corrigidas automaticamente. Quando houver questões discursivas, a resposta fica aguardando avaliação manual. A revisão é liberada após o envio, conforme as regras do simulado.'],
    ['Posso fazer pelo celular?', 'Sim. Você pode simular pelo navegador do celular ou do computador, sem instalar um aplicativo.'],
    ['O acesso é vitalício?', 'Sim. A oferta prevê acesso vitalício aos simulados e materiais disponibilizados nessa mesma oferta, incluindo novos conteúdos nela adicionados.'],
    ['O acesso inclui a inscrição ou garante aprovação no exame?', 'Não. A plataforma oferece prática por simulação e materiais de apoio. A inscrição no exame oficial é feita separadamente, e a aprovação depende do seu desempenho no processo oficial.'],
  ];
  const accessLink = data.user?.hasAccess ? '#/simulados' : '#/checkout';
  return `${header()}
    <main id="main" class="public-wrap">
      <section class="hero">
        <div>
          <div class="eyebrow">Simulador de provas e certificações</div>
          <h1>Treine antes da prova.<br>Chegue mais <em>preparado.</em></h1>
          <p class="intro">Escolha uma certificação disponível, faça simulados, revise suas respostas e acompanhe seu desempenho. Use os materiais de apoio para reforçar os assuntos em que precisa melhorar.</p>
          <div class="hero-price"><strong>R$ 29,90</strong><p>Pagamento único. Acesso vitalício.<br>Simulados e materiais da oferta incluídos.</p></div>
          ${link('Quero acesso aos simulados ' + icon('arrow',16), accessLink, 'gold')}
          <a class="planner-jump" href="#calculadora" data-scroll="calculadora">Planejar minha prática ${icon('right',13)}</a>
          <p class="fine">Sem mensalidade e sem renovação paga.</p>
        </div>
        <div class="hero-visual">
          <div class="preview-window">
            <div class="preview-top"><span class="preview-dot"></span><span class="preview-dot"></span><span class="preview-dot"></span><span class="spacer"></span>SEU SIMULADOR DE PROVAS</div>
            <div class="preview-main">
              <div class="eyebrow">Uma tentativa de cada vez</div>
              <h3>Pratique. Revise. Evolua.</h3>
              <div class="preview-feature">
                ${badge('ANCORD · ADMINISTRAÇÃO DE RISCO','outline')}
                <h3 class="preview-question">Uma carteira de títulos prefixados vale R$ 200.000 e tem duration modificada de 4,2 anos. Após alta paralela de 75 pontos-base nos juros, qual é seu valor aproximado, desconsiderando convexidade e mantendo os spreads constantes?</h3>
                <div class="preview-answers"><span><b>A</b> R$ 206.300,00</span><span><b>B</b> R$ 199.370,00</span><span><b>C</b> R$ 193.700,00</span><span><b>D</b> R$ 191.600,00</span></div>
                <p style="margin-bottom:0">Questão autoral, não oficial. <a class="preview-source" href="https://certpessoas.fgv.br/ancord/arquivos/RegulamentoAI.htm" target="_blank" rel="noopener noreferrer">Tema previsto no programa ANCORD.</a></p>
              </div>
              <div class="preview-footer">
                <div class="mini-card">${icon('check',15)}<b>Revisão das respostas</b>Entenda cada tentativa.</div>
                <div class="mini-card">${icon('chart',15)}<b>Histórico de desempenho</b>Acompanhe seus resultados.</div>
              </div>
            </div>
          </div>
          <div class="preview-caption">${icon('info',13)} Prévia do simulador. Não representa resultados de alunos.</div>
        </div>
      </section>
      <div class="trust-strip">
        <div>${icon('list',20)} Simulados das opções disponíveis.</div>
        <div>${icon('chart',19)} Suas tentativas, no seu histórico.</div>
        <div>${icon('infinity',20)} Um pagamento. Todo o conteúdo da oferta.</div>
      </div>
      <section class="section">
        <div class="section-head"><div><div class="eyebrow">Prática que orienta sua preparação</div><h2>Descubra seus pontos fortes.<br>Encontre o que precisa revisar.</h2></div><p>Uma simulação mostra como você respondeu. A revisão ajuda a decidir o próximo passo.</p></div>
        <div class="benefits">${benefits.map(([i,t,p])=>`<div class="benefit">${icon(i,25)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div>
      </section>
      ${practicePlannerSection()}
      <section id="como-funciona" class="how-section">
        <div class="eyebrow">Como funciona</div><h2>Escolha. Simule. Revise.</h2>
        <div class="steps">${[
          ['Escolha sua prova', 'Garanta seu acesso e selecione uma das provas ou certificações disponíveis.'],
          ['Faça uma simulação', 'Confira as regras, responda às questões e pratique com o tempo configurado, quando houver.'],
          ['Revise seu desempenho', 'Consulte o resultado, revise as respostas e use os materiais de apoio antes da próxima tentativa.'],
        ].map(([t,p],i)=>`<div><div class="step-num">0${i+1}</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>
      </section>
      <section id="incluido" class="section included">
        <div><div class="eyebrow">O que está incluído</div><h2>Simulados para praticar.<br>Apoio para ir além.</h2>
          <ul class="check-list">${[
            'Simulados organizados por prova ou certificação.',
            'Regras e duração próprias de cada simulado.',
            'Correção e revisão conforme o tipo de questão.',
            'Histórico de tentativas e indicadores de desempenho.',
            'Materiais de apoio separados por assunto.',
            'Novos simulados e materiais adicionados à mesma oferta.',
          ].map(x=>`<li>${icon('check',17)}${x}</li>`).join('')}</ul>
          <p class="small muted">Você acessa todas as opções publicadas na oferta. O catálogo não abrange necessariamente todas as provas ou certificações existentes.</p>
        </div>
        <div>${['ancord','pqo'].map(id=>`<div class="prep-preview"><div class="actions"><h3>${E(prepName(id))}</h3><span class="spacer"></span>${badge('Exemplo demonstrativo')}</div><p>${id==='ancord'?'Prévia de simulados e materiais de apoio. As questões de exemplo precisam de revisão antes da publicação comercial.':'Uma certificação distinta de ANCORD, com seus próprios exemplos de questões e configurações.'}</p></div>`).join('')}
          <p class="inline-note">${icon('info',13)} Os exemplos desta prévia validam o simulador. Não representam o formato oficial dos exames nem conteúdo completo pronto para venda.</p>
        </div>
      </section>
      <section class="offer">
        <div><div class="eyebrow">Sua próxima tentativa começa aqui</div><h2>Mais prática para a prova.<br>Um único pagamento.</h2><p>Tenha acesso aos simulados e materiais de apoio disponíveis na plataforma. Repita a prática, revise suas respostas e acompanhe seu desempenho sem pagar mensalidade.</p></div>
        <div class="offer-box"><div class="small">Pagamento único · acesso vitalício</div><div class="offer-price">R$ 29,90</div><p class="small" style="margin:0 0 20px">Todos os simulados e materiais da oferta incluídos.</p>${link('Quero começar a simular '+icon('arrow',15), accessLink, 'gold')}<p class="fine">Pré-lançamento: vendas ainda não habilitadas.</p></div>
      </section>
      <section class="section faq"><div class="eyebrow" style="text-align:center">Tire suas dúvidas</div><h2>Antes da primeira simulação.</h2>${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>
      <footer class="public-footer"><div>${brand()}<p style="margin-top:15px">Plataforma independente de simulação, sem vínculo oficial com entidades certificadoras. Identificação do responsável, suporte e política de reembolso serão definidos antes da publicação.</p></div><div class="actions"><a href="#" data-action="legal" data-kind="terms">Termos de uso</a><a href="#" data-action="legal" data-kind="privacy">Privacidade</a>${button('Conhecer o simulador','demo-student','secondary compact')}</div></footer>
    </main>`;
}

const plannerDraft={mode:'illustrative',dailyMinutes:90,illustrativeTarget:80,quiz:'',sessions:10,questions:30,minutes:30,review:15,days:'',current:'',target:''};
function practicePlannerSection(){
  const planField=(name,label,value,extra='')=>`<div class="field"><label for="plan-${name}">${label}</label><input id="plan-${name}" data-plan="${name}" type="number" value="${E(value)}" ${extra}></div>`;
  return `<section id="calculadora" class="section practice-planner" aria-labelledby="planner-title">
    <div class="section-head"><div><div class="eyebrow">Calculadora de prática · cenários e planejamento</div><h2 id="planner-title">Explore seu ritmo.<br>Visualize a evolução.</h2></div><p>Simule uma porcentagem hipotética de aprovação conforme a quantidade de tentativas ou planeje o volume e o tempo de prática.</p></div>
    <div class="research-summary">${icon('book',22)}<div><strong>Pesquisa sobre prática — separada do cenário fictício.</strong><p>Uma meta-análise reuniu 222 estudos e 48.478 estudantes e encontrou benefício médio no desempenho acadêmico. Isso não é uma taxa de aprovação no seu exame. <a href="https://pubmed.ncbi.nlm.nih.gov/33683913/" target="_blank" rel="noopener noreferrer">Yang et al., 2021 ${icon('arrow',12)}</a></p></div></div>
    <div class="planner-grid">
      <div class="card planner-controls">
        <div class="card-header"><div><h3>Monte seu cenário.</h3><p>Escolha o modo abaixo e ajuste a quantidade e o ritmo de prática.</p></div>${icon('list',19)}</div>
        <div class="field"><label for="plan-mode">Modo da calculadora</label><select id="plan-mode" data-plan="mode"><option value="illustrative" ${plannerDraft.mode==='illustrative'?'selected':''}>Simulação hipotética de aprovação</option><option value="planning" ${plannerDraft.mode==='planning'?'selected':''}>Planejamento de volume e tempo</option></select></div>
        <div id="illustrative-warning" class="alert demo-warning">${icon('info',17)}<div><strong>Demonstração com números inventados.</strong><br>O percentual abaixo não é uma chance real de aprovação e não foi obtido das pesquisas.</div></div>
        <div class="field"><label for="plan-quiz">Formato de referência</label><select id="plan-quiz" data-plan="quiz"><option value="">Planejamento livre</option>${data.quizzes.map(q=>`<option value="${q.id}" ${plannerDraft.quiz===q.id?'selected':''}>${E(q.name)} · demonstração</option>`).join('')}</select><small>As opções do catálogo são exemplos demonstrativos, não formatos oficiais.</small></div>
        ${planField('sessions','Simulações planejadas',plannerDraft.sessions,'min="1" max="1000" step="1"')}
        <div class="planner-presets" role="group" aria-label="Exemplos de quantidade"><span>Experimente:</span>${[1,10,1000].map(n=>`<button class="btn secondary compact" data-action="plan-preset" data-count="${n}" aria-pressed="${Number(plannerDraft.sessions)===n}">${n===1000?'1.000':n} ${n===1?'vez':'vezes'}</button>`).join('')}</div>
        <div class="field-row">${planField('questions','Questões por simulação',plannerDraft.questions,'min="1" max="500" step="1"')}${planField('minutes','Minutos por simulação',plannerDraft.minutes,'min="1" max="480" step="1"')}</div>
        <div class="field-row">${planField('review','Minutos de revisão por tentativa',plannerDraft.review,'min="0" max="240" step="1"')}${planField('days','Dias disponíveis (opcional)',plannerDraft.days,'min="1" max="3650" step="1" placeholder="Ex.: 30"')}</div>
        <div id="illustrative-controls" class="field-row">${planField('dailyMinutes','Minutos disponíveis por dia',plannerDraft.dailyMinutes,'min="1" max="720" step="1"')}${planField('illustrativeTarget','Meta hipotética de aprovação (%)',plannerDraft.illustrativeTarget,'min="21" max="94" step="1"')}</div>
        <details class="planner-goal"><summary>Comparar meu acerto com uma meta</summary><p>Preencha sua taxa de acerto e uma meta pessoal. Não são chances de aprovação e a meta não é um corte oficial.</p><div class="field-row">${planField('current','Meu acerto atual (%)',plannerDraft.current,'min="0" max="100" step="0.1" placeholder="Ex.: 55"')}${planField('target','Minha meta de acerto (%)',plannerDraft.target,'min="0" max="100" step="0.1" placeholder="Ex.: 80"')}</div></details>
      </div>
      <div class="planner-output-wrap"><div id="planner-output" aria-live="polite" aria-atomic="true"></div><div class="planner-limit"><strong>Quantos simulados aumentam minha chance de passar?</strong><p>As fontes consultadas não fornecem uma porcentagem pessoal para 1, 10 ou 1.000 tentativas. No modo demonstrativo, os números são fictícios. No planejamento, são calculados volume e tempo. Nenhum dos modos estima a probabilidade real de aprovação nem quantas tentativas bastam para passar.</p></div></div>
    </div>
    <details class="research-details"><summary>Ver pesquisas, métodos e limites ${icon('right',14)}</summary><div class="research-body">
      <article><h3>1. Benefício médio da prática com testes</h3><p>Yang et al. (2021) analisaram 222 estudos, com 48.478 estudantes. Encontraram efeito médio padronizado de g = 0,499 sobre desempenho acadêmico. Esse número não significa 49,9% de aumento na chance de passar. Formato, feedback e repetições estão entre os fatores que modificam o efeito.</p><a href="https://pubmed.ncbi.nlm.nih.gov/33683913/" target="_blank" rel="noopener noreferrer">Ler o resumo original no PubMed ${icon('arrow',12)}</a></article>
      <article><h3>2. Aprovação em disciplinas não é uma previsão para certificações</h3><p>Sotola e Crede (2021) reuniram 52 amostras sobre quizzes em turmas. No recorte sobre aprovação em disciplinas (5 amostras, 1.004 participantes), relataram uma razão de chances de 2,566. Trata-se de uma associação, não de um multiplicador da probabilidade pessoal nem de um ganho por simulado. O estudo não valida uma curva de 1 a 1.000 tentativas para ANCORD, PQO ou para esta plataforma.</p><a href="https://link.springer.com/article/10.1007/s10648-020-09563-9" target="_blank" rel="noopener noreferrer">Ler o resumo original na Springer ${icon('arrow',12)}</a></article>
      <article><h3>3. Repetição com espaçamento e recuperação correta</h3><p>Rawson e Dunlosky (2022) discutem a prática até conseguir recuperar uma informação corretamente e sua retomada em outras sessões espaçadas. Essa evidência orienta a forma de praticar; não define uma quantidade universal de provas nem garante aprovação.</p><a href="https://journals.sagepub.com/doi/full/10.1177/09637214221100484" target="_blank" rel="noopener noreferrer">Ler a revisão original na SAGE ${icon('arrow',12)}</a></article>
      <div class="planner-method"><h3>O que a calculadora realmente calcula</h3><p>Respostas planejadas = simulações × questões. Tempo total = simulações × (minutos de simulação + revisão). A diferença para a meta é medida em pontos percentuais. Repetir a mesma questão não conta como uma questão nova. Não há conversão desses valores em probabilidade de aprovação.</p><p><strong>Modo fictício:</strong> índice = 95 − 75 × exp(−0,12 × tentativas). O ponto inicial de 20%, o teto de 95% e a taxa 0,12 são escolhas inventadas apenas para esta demonstração. O total de tentativas até a meta usa a inversa dessa curva; o prazo divide as tentativas restantes pela capacidade diária de simulações completas com revisão. Nenhum parâmetro foi calibrado por pesquisas ou resultados de usuários.</p><p>Fontes consultadas em 06/11/2026. As pesquisas não avaliaram o Simulou Passou. Formatos e contextos variam entre os estudos.</p></div>
    </div></details>
  </section>`;
}
function renderIllustrativeScenario(plan){
  const scenario=calculateIllustrativeScenario({sessions:plan.sessions,minutesPerSimulation:Number(plannerDraft.minutes)+Number(plannerDraft.review),minutesPerDay:Number(plannerDraft.dailyMinutes),target:Number(plannerDraft.illustrativeTarget)});
  if(!scenario.valid)return `<div class="card">${notice('No cenário fictício, informe de 1 a 720 minutos disponíveis por dia e uma meta hipotética de 21% a 94%.','error')}</div>`;
  const n=v=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(v);
  const time=scenario.remainingDays===null?'Ajuste o tempo diário':scenario.remainingDays===0?'Meta hipotética atingida':scenario.remainingDays+' '+(scenario.remainingDays===1?'dia de prática':'dias de prática');
  return `<div class="card dark planner-result demo-result">
    ${badge('CENÁRIO HIPOTÉTICO · SEM VALIDAÇÃO','outline')}
    <div class="planner-big demo-index">${n(scenario.index)}<span>%</span></div>
    <h3 class="demo-index-label">Porcentagem hipotética de aprovação</h3>
    <p class="demo-notice">Neste cenário hipotético, mais simulações aumentam o percentual ilustrativo. Os números são inventados e não estimam sua chance real no exame.</p>
    <div class="demo-progress" role="img" aria-label="Porcentagem hipotética de aprovação de ${n(scenario.index)} por cento; não estima a chance real no exame"><span style="width:${scenario.index}%"></span></div>
    <div class="demo-comparison"><span>Após ${n(plan.sessions)} ${plan.sessions===1?'simulação':'simulações'}</span><span>Meta hipotética: ${n(scenario.target)}%</span></div>
    <div class="planner-metrics"><div><strong>${scenario.targetSessions}</strong><span>simulações totais até a meta hipotética</span></div><div><strong>${scenario.remainingSessions}</strong><span>simulações restantes no cenário</span></div></div>
    <div class="demo-time"><span>Prazo hipotético para a meta</span><strong>${time}</strong><p>${scenario.remainingDays===null?'Seu tempo diário não comporta uma simulação com revisão. Aumente a disponibilidade ou reveja a duração.':scenario.remainingDays===0?'O número informado alcança a meta deste modelo inventado. Isso não significa aprovação no exame.':`Com ${scenario.sessionsPerDay} simulação(ões) por dia, contando ${plannerDraft.review} minutos de revisão por tentativa.`}</p></div>
    <div class="planner-percent"><span>Chance de aprovação (cenário hipotético)</span><strong class="approval-percentage">${n(scenario.index)}%</strong><p class="percentage-disclosure">Percentual simulado, sem validação estatística. Não corresponde à sua chance real no exame.</p></div>
  </div><div class="card planner-goal-result"><h3>Como o ritmo afeta o prazo</h3><p>Neste modelo, mais tentativas elevam a porcentagem hipotética de aprovação. Mais tempo disponível por dia permite concluir essas tentativas antes e reduz o prazo até a meta. A porcentagem é apenas ilustrativa, sem medir qualidade de estudo ou resultado no exame.</p></div>`;
}

function updatePracticePlanner(){
  const output=$('#planner-output');if(!output)return;
  for(const el of document.querySelectorAll('[data-plan]'))plannerDraft[el.dataset.plan]=el.value;
  const illustrative=plannerDraft.mode==='illustrative';
  $('#illustrative-warning').hidden=!illustrative;$('#illustrative-controls').hidden=!illustrative;
  $('.planner-goal').hidden=illustrative;$('#plan-days').closest('.field').hidden=illustrative;
  const plan=calculatePracticePlan(illustrative?{...plannerDraft,current:'',target:'',days:''}:plannerDraft);
  for(const el of document.querySelectorAll('[data-plan]'))el.setAttribute('aria-invalid',String(!!plan.errors[el.dataset.plan]));
  for(const b of document.querySelectorAll('[data-action="plan-preset"]'))b.setAttribute('aria-pressed',String(Number(plannerDraft.sessions)===Number(b.dataset.count)));
  if(!plan.valid){output.innerHTML=`<div class="card">${notice('Ajuste os valores para calcular: '+E(Object.values(plan.errors)[0]),'error')}</div>`;return;}
  if(illustrative){output.innerHTML=renderIllustrativeScenario(plan);return;}
  const illustrativePercent=calculateIllustrativeScenario({sessions:plan.sessions,minutesPerSimulation:Number(plannerDraft.minutes)+Number(plannerDraft.review),minutesPerDay:90,target:80}).index;
  const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n);
  let goal='Informe seu acerto atual e sua meta para calcular a diferença entre eles.';
  if(plan.gapPoints!==null)goal=plan.gapPoints===0?`Seu acerto informado já alcança essa meta. Isso não determina sua chance no exame oficial.`:`Faltam <strong>${fmt(plan.gapPoints)} pontos percentuais</strong> entre seu acerto informado e sua meta. A quantidade de tentativas necessária para avançar não pode ser deduzida desses dois valores.`;
  output.innerHTML=`<div class="card dark planner-result">${badge('Planejamento · não é previsão de aprovação','outline')}<div class="planner-big">${fmt(plan.sessions)}</div><p>${plan.sessions===1?'simulação planejada':'simulações planejadas'}</p><div class="planner-metrics"><div><strong>${fmt(plan.totalResponses)}</strong><span>respostas planejadas</span></div><div><strong>${formatPlanTime(plan.totalMinutes)}</strong><span>de prática e revisão</span></div></div><p class="planner-breakdown">${formatPlanTime(plan.simulationMinutes)} simulando + ${formatPlanTime(plan.reviewMinutes)} revisando.<br>O volume pode incluir as mesmas questões repetidas.</p>${plan.minutesPerDay!==null?`<div class="planner-daily"><strong>${new Intl.NumberFormat('pt-BR',{maximumFractionDigits:4}).format(plan.sessionsPerDay)} simulações por dia, em média</strong><p>${plan.minutesPerDay<1?'Menos de 1 min':formatPlanTime(Math.round(plan.minutesPerDay))} por dia no período informado.${plan.minutesPerDay>1440?' Este plano ultrapassa 24 horas por dia. Reduza o volume ou amplie o prazo.':''}</p></div>`:''}<div class="planner-percent"><span>Chance de aprovação (cenário hipotético)</span><strong class="approval-percentage">${fmt(illustrativePercent)}%</strong><p class="percentage-disclosure">Percentual simulado pelo modelo fictício, sem relação estatística com a aprovação real.</p></div></div><div class="card planner-goal-result"><h3>Sua meta de acerto</h3><p>${goal}</p></div>`;
}

function authPage(kind){if(data?.local===false)return cloudAuthPage(kind,{bar,brand,field,icon});const register=kind==='cadastro',recovery=kind==='recuperar',reset=kind==='redefinir';const title=register?'Seu próximo passo começa aqui.':recovery?'Vamos recuperar seu acesso.':reset?'Crie uma nova senha.':'Bom ter você de volta.';return `${bar()}<main id="main" class="auth-page"><aside class="auth-story">${brand()}<div><div class="eyebrow" style="color:#cfb17b">Simule com um objetivo.</div><h1>A próxima prova<br>merece uma boa<br><em>simulação.</em></h1><p>Faça simulados para seu objetivo, revise as respostas e acompanhe como você se sai a cada tentativa.</p></div><p class="small">Prévia de validação local · Simulou Passou<br>Sem cobrança e sem envio de e-mails.</p></aside><section class="auth-panel"><div class="auth-card"><a class="auth-back" href="#/">${icon('left',15)} Voltar à página inicial</a><h1>${title}</h1><p>${register?'Crie sua conta. A compra é simulada na próxima etapa.':recovery?'Informe o e-mail usado no cadastro desta prévia.':reset?'O novo acesso será válido apenas na sua conta.':'Entre na sua conta para continuar suas simulações.'}</p><form data-form="${register?'register':recovery?'recover':reset?'reset':'login'}">${register?field('name','Seu nome','','text','required autocomplete="name" placeholder="Como podemos chamar você?"'):''}${!reset?field('email','E-mail','','email','required autocomplete="email" placeholder="voce@exemplo.com"'):''}${!recovery?field('password',reset?'Nova senha':'Senha','','password',`required minlength="8" maxlength="128" autocomplete="${register||reset?'new-password':'current-password'}" placeholder="${register||reset?'Pelo menos 8 caracteres':'Sua senha'}"`):''}<div class="form-error" role="alert"></div><button class="btn full" type="submit">${register?'Criar minha conta':recovery?'Gerar recuperação local':reset?'Salvar nova senha':'Entrar na minha conta'} ${icon('arrow',15)}</button></form><div id="recovery-result"></div>${!recovery&&!reset?`<div class="auth-links">${register?'<span>Já tem uma conta?</span><a href="#/entrar">Entrar</a>':'<a href="#/recuperar">Esqueci minha senha</a><a href="#/cadastro">Criar conta</a>'}</div><div class="divider">OU CONHEÇA A ESTRUTURA</div><div class="demo-options">${button(icon('book',16)+' Explorar como aluno','demo-student','secondary full')}${button(icon('shield',16)+' Abrir administração de demonstração','demo-master','secondary full')}</div><p class="fine">Os botões acima abrem perfis de teste locais. Não são contas de produção nem usam senha compartilhada.</p>`:`<div class="auth-links"><a href="#/entrar">Voltar ao login</a></div>`}</div></section></main>`;}
const nav=[['inicio','grid','Meu painel'],['simulados','list','Simulados'],['preparacoes','target','Provas e certificações'],['materiais','book','Materiais de apoio'],['anotacoes','file','Anotações'],['plano','clock','Meu plano'],['revisao','flag','Caderno de erros'],['foco','target','Modo foco'],['desempenho','chart','Meu desempenho'],['conta','user','Minha conta']];
function shell(content,active,title){const u=data.user;return `<aside class="sidebar" id="sidebar">${brand()}<button class="icon-btn mobile-menu sidebar-close" data-action="menu" aria-label="Fechar navegação">${icon('close',20)}</button><div class="sidebar-intro">Sua área de simulação</div><nav class="app-nav" aria-label="Área de membros">${nav.map(([r,i,t])=>`<a href="#/${r}" class="${active===r?'active':''}">${icon(i,18)}${t}</a>`).join('')}${u.role==='master'?`<div class="nav-admin"><a href="#/admin" class="${active==='admin'?'active':''}">${icon('shield',18)}Administração</a></div>`:''}</nav><div class="sidebar-bottom"><div class="serif">Simule.<br>Revise.<br><em>Tente de novo.</em></div><p>Seu espaço de simulação.<br>Pratique e acompanhe sua evolução.</p><button class="btn text" style="color:#b9cccd;margin-top:15px" data-action="logout">${icon('logout',15)} Sair da conta</button></div></aside><button class="sidebar-backdrop" data-action="menu" aria-label="Fechar menu"></button><div class="app-area"><header class="app-header"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir navegação" aria-expanded="false" aria-controls="sidebar">${icon('menu',20)}</button><span>Simulou Passou</span><span>/</span><strong>${title}</strong></div><div class="user-chip">${u.role==='master'?badge('Administração'):'<span class="desktop-only small muted">Sua área de simulação</span>'}<span class="avatar">${E(u.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span><span class="user-name">${E(u.name.split(' · ')[0])}</span></div></header><main id="main" class="app-content"><div class="app-demo">${icon('info',14)}<span>${data.local===false?'PRÉ-LANÇAMENTO · Conteúdo demonstrativo. Vendas ainda não habilitadas.':'PRÉVIA LOCAL · Conteúdos e contas de teste. Pagamentos simulados.'}</span><a href="#/">Ver página de vendas ${icon('arrow',12)}</a></div>${content}</main></div><nav class="mobile-bottom-nav" aria-label="Acesso rápido">${[['inicio','grid','Meu painel'],['simulados','list','Simulados'],['anotacoes','file','Anotações']].map(([r,i,t])=>`<a href="#/${r}" class="${active===r?'active':''}">${icon(i,19)}<span>${t}</span></a>`).join('')}</nav>`;}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;}
function prepCard(p){const mats=data.materials.filter(m=>m.prepId===p.id),qs=data.quizzes.filter(q=>q.prepId===p.id),done=mats.filter(m=>data.completed.some(c=>c.materialId===m.id)).length;return `<article class="card prep-card ${p.status==='draft'?'gray':p.color==='blue'?'blue':''}"><div class="prep-monogram">${E(p.name[0])}</div>${badge(p.status==='draft'?'Em preparação':'Demonstração',p.status==='draft'?'gray':'')}<h3>${E(p.name)}</h3><p class="description">${E(p.description)}</p><div class="meta"><span>${mats.length} materiais</span><span>${qs.length} simulados</span></div>${p.status==='published'?`${link('Ver simulados e apoio '+icon('right',13),'#/preparacoes?prep='+p.id,'secondary compact')}<div class="progress"><span style="width:${mats.length?done/mats.length*100:0}%"></span></div><p class="fine">${done} de ${mats.length} materiais concluídos</p>`:'<p class="small muted">Novos conteúdos, sem data definida.</p>'}</article>`;}
function stat(label,value,foot,i){return `<div class="card"><div class="stat-label">${icon(i,16)}${label}</div><div class="stat-number">${value}</div><p class="stat-foot">${foot}</p></div>`;}
function attemptRows(list){return list.map(a=>`<a class="list-row" href="#/tentativa/${a.id}"><span class="list-icon">${icon(a.status==='in_progress'?'clock':'list',17)}</span><div class="list-main"><h3>${E(a.quizName)}</h3><p>${E(prepName(a.prepId))} · ${date(a.startedAt)}${a.isTest?' · teste administrativo':''}</p></div><div class="list-tail">${statusBadge(a)}<p class="small muted" style="margin-top:5px">${a.result?pct(a.result.accuracy)+' de acerto objetivo':'Continuar '+icon('right',12)}</p></div></a>`).join('');}
function home(){return personalDashboard();}
function prepFilter(value='',withAll=true){return `<select class="filter-select" aria-label="Filtrar por prova ou certificação" data-filter="prep">${withAll?'<option value="">Todas as provas e certificações</option>':''}${data.preparations.filter(p=>p.status==='published').map(p=>`<option value="${E(p.id)}" ${p.id===value?'selected':''}>${E(p.name)}</option>`).join('')}</select>`;}
function preparations(filter){if(filter){const p=data.preparations.find(p=>p.id===filter);if(!p||p.status!=='published')return empty('Preparação não disponível.','Escolha uma preparação publicada.',link('Ver preparações','#/preparacoes'));const mats=data.materials.filter(m=>m.prepId===p.id),quizzes=data.quizzes.filter(q=>q.prepId===p.id);return `<a class="back-link" href="#/preparacoes">${icon('left',14)} Todas as provas e certificações</a>${heading('Preparação · conteúdo demonstrativo',E(p.name),E(p.description))}${notice('Materiais e exercícios autorais de exemplo. O conteúdo técnico e o programa oficial precisam de revisão antes da publicação.')}<div class="section-title"><h2>Materiais de apoio</h2></div><div class="material-grid">${mats.map(materialCard).join('')||empty('Nenhum material publicado.','Acompanhe novos conteúdos desta preparação.')}</div><div class="section-title"><h2>Simule para este objetivo</h2></div><div class="grid-2">${quizzes.map(quizCard).join('')||empty('Nenhum simulado publicado.','Novos exercícios podem ser incluídos nesta preparação.')}</div>`;}return `${heading('Escolha seu objetivo','Para qual prova você quer simular?','Encontre os simulados e materiais de apoio de cada certificação. Todas as opções publicadas da oferta ficam disponíveis na mesma conta.')}<div class="grid-3">${data.preparations.map(prepCard).join('')}</div><p class="inline-note">As preparações ANCORD e PQO são distintas. Os exemplos desta prévia não representam o formato oficial dos exames.</p>`;}
function materialCard(m){const done=data.completed.some(c=>c.materialId===m.id);return `<article class="card material-card"><div class="actions"><span class="list-icon">${icon(m.format==='link'?'arrow':'file',20)}</span><span class="spacer"></span>${badge(done?'Concluído':m.format==='link'?'Link de estudo':'Leitura',done?'green':'gray')}</div><div><div class="eyebrow" style="margin:0 0 7px">${E(prepName(m.prepId))}</div><h3>${E(m.title)}</h3><p class="small muted" style="margin-top:8px">${E(m.module)}</p></div><div class="actions">${link(done?'Revisar material':'Abrir material','#/material/'+m.id,'secondary compact')}${icon('right',15)}</div></article>`;}
function materials(filter){const mats=data.materials.filter(m=>!filter||m.prepId===filter);return `${heading('Apoio à simulação','Materiais para reforçar sua prática.','Use os materiais disponíveis para revisar os assuntos e voltar ao simulado com mais clareza.')}<div class="toolbar">${prepFilter(filter)}<span class="count">${mats.length} materiais disponíveis</span></div>${[...new Set(mats.map(m=>m.module))].map(module=>`<h2 class="module-heading">${E(module)}</h2><div class="material-grid">${mats.filter(m=>m.module===module).map(materialCard).join('')}</div>`).join('')||empty('Nenhum material encontrado.','Escolha outra preparação.')}`;}
function reader(m){const done=data.completed.some(c=>c.materialId===m.id);return `<div class="reader"><a class="back-link" href="#/materiais?prep=${m.prepId}">${icon('left',14)} Voltar aos materiais</a><div class="card"><div class="actions">${badge('Conteúdo demonstrativo')}<span class="spacer"></span>${badge(done?'Leitura concluída':'Material de apoio',done?'green':'gray')}</div><div class="eyebrow" style="margin-top:28px">${E(prepName(m.prepId))} · ${E(m.module)}</div><h1>${E(m.title)}</h1><article>${m.format==='link'?`${notice('Link de estudo cadastrado na administração. O conteúdo externo não é armazenado por esta prévia.') }<a class="btn secondary" href="${E(m.body)}" target="_blank" rel="noopener noreferrer">Abrir referência externa ${icon('arrow',15)}</a>`:m.body.split(/\n\s*\n/).map(p=>`<p>${E(p)}</p>`).join('')}</article><footer class="actions">${button(icon('check',16)+(done?' Marcar como não concluído':' Marcar como concluído'),'complete-material','gold')}<span class="small muted">O progresso fica salvo na sua conta.</span></footer></div></div>`;}
function quizCard(q){const active=data.attempts.find(a=>a.quizId===q.id&&a.status==='in_progress');return `<article class="card quiz-card"><div class="actions">${badge(prepName(q.prepId),'gray')}${q.essayCount?badge('Correção manual'):''}</div><h3>${E(q.name)}</h3><p class="description">${E(q.description)}</p><div class="quiz-details"><span>${icon('list',14)}${q.count} questões</span><span>${icon('clock',14)}${q.durationMinutes?q.durationMinutes+' min':'Sem limite de tempo'}</span><span>${q.essayCount?'Misto':'Objetivo'}</span></div><div class="actions">${link(active?'Continuar tentativa':'Conhecer simulado',active?'#/tentativa/'+active.id:'#/simulado/'+q.id,'secondary compact')}<span class="small muted">${q.totalPoints} pontos</span></div></article>`;}
function quizzes(filter){const qs=data.quizzes.filter(q=>!filter||q.prepId===filter);return `${heading('Simulador de provas','Seu próximo simulado.','Escolha sua prova ou certificação e confira o formato, o tempo e as regras de cada simulado.')}<div class="toolbar">${prepFilter(filter)}<span class="count">${qs.length} simulados disponíveis</span></div><div class="grid-2">${qs.map(quizCard).join('')}</div><p class="inline-note">As configurações desta prévia são exemplos de treinamento. Não correspondem ao formato oficial de uma certificação.</p>`;}
function quizStart(q){return `<div class="quiz-start"><a class="back-link" href="#/simulados">${icon('left',14)} Voltar aos simulados</a><div class="card">${badge(prepName(q.prepId),'gray')}<div class="eyebrow" style="margin-top:27px">Antes de começar</div><h1>${E(q.name)}</h1><p class="description">${E(q.description)}</p><dl class="rule-grid"><div><dt>QUESTÕES</dt><dd>${q.count} no total · ${q.objectiveCount} objetivas${q.essayCount?' e '+q.essayCount+' discursiva(s)':''}</dd></div><div><dt>TEMPO</dt><dd>${q.durationMinutes?q.durationMinutes+' minutos a partir do início':'Sem limite de tempo'}</dd></div><div><dt>PONTUAÇÃO</dt><dd>${q.totalPoints} pontos · pesos por questão<br>Acerto objetivo calculado sobre todas as objetivas.</dd></div><div><dt>CRITÉRIO DE CONCLUSÃO</dt><dd>${q.passPercent===null?'Sem meta de aprovação configurada':q.passPercent+'% da pontuação total'}<br>${q.essayCount?'Respostas abertas passam por correção manual.':'Correção automática das objetivas.'}</dd></div><div><dt>ALTERNATIVAS</dt><dd>${q.optionCounts.join(' ou ')} por questão objetiva</dd></div><div><dt>NOVAS TENTATIVAS E REVISÃO</dt><dd>${q.maxAttempts?'Até '+q.maxAttempts+' tentativas':'Tentativas sem limite configurado'}<br>${q.review?'Revisão liberada após finalizar.':'Revisão não disponibilizada.'}</dd></div></dl>${notice('As respostas são salvas automaticamente. Se a conexão com o servidor for interrompida, o rascunho fica neste navegador até a reconexão.')}<div class="actions" style="margin-top:25px">${button('Iniciar simulado '+icon('arrow',16),'start-quiz','gold')}<span class="small muted">Exercícios autorais demonstrativos.</span></div></div></div>`;}
function draftKey(){return 'logos-study-draft:'+data.user.id+':'+currentAttempt.id;}
function setDraft(){try{localStorage.setItem(draftKey(),JSON.stringify({answers:currentAttempt.answers,flags:currentAttempt.flags,pending:true}));}catch{}dirty=true;saveProblem=false;clearTimeout(saveTimer);saveTimer=setTimeout(saveDraft,600);updateSaveState('Salvando rascunho…');}
function updateSaveState(msg){const el=$('#save-state');if(el){el.classList.toggle('error',saveProblem);el.innerHTML=icon(saveProblem?'info':'check',12)+E(msg||'Respostas salvas neste computador');}}
async function saveDraft(){if(!currentAttempt||currentAttempt.status!=='in_progress'||saving||!dirty)return;const id=currentAttempt.id;const body={answers:{...currentAttempt.answers},flags:[...currentAttempt.flags]};saving=true;dirty=false;try{await api('/attempts/'+id+'/save',{method:'POST',body});if(!dirty)try{localStorage.removeItem(draftKey());}catch{}saveProblem=false;updateSaveState(dirty?'Salvando novas respostas…':'Respostas salvas neste computador');}catch(e){dirty=true;saveProblem=true;updateSaveState('Rascunho neste navegador · reconecte para sincronizar');if(e.status===409){dirty=false;go('/tentativa/'+id);}}finally{saving=false;if(dirty&&!saveProblem)saveDraft();}}
function attempt(a){const q=a.questions[questionIndex];return `${heading(E(prepName(a.prepId)),E(a.quizName),'Mantenha o seu ritmo. Você pode navegar entre as questões e marcar as que deseja revisar.',a.isTest?badge('Teste administrativo'):'' )}<div class="attempt-layout"><section class="card question-card"><div class="question-overline"><span>QUESTÃO ${questionIndex+1} DE ${a.questions.length} · ${E(q.subject)}</span><span>${q.type==='essay'?'Discursiva':'Objetiva'} · ${q.points} ponto(s)</span></div><h2 class="question-prompt">${E(q.prompt)}</h2>${q.type==='objective'?`<div class="options" role="radiogroup" aria-label="Alternativas">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${a.answers[q.id]===String(i)?'checked':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${E(o)}</span></label>`).join('')}</div>`:`<label class="screen-reader" for="essay-answer">Sua resposta</label><textarea id="essay-answer" class="answer-area" maxlength="4000" placeholder="Escreva sua resposta com suas palavras…">${E(a.answers[q.id]||'')}</textarea><p class="fine">Até 4.000 caracteres · correção manual após o envio.</p>`}<div class="question-controls"><button class="flag-btn ${a.flags.includes(q.id)?'active':''}" data-action="flag">${icon('flag',15)}${a.flags.includes(q.id)?'Marcada para revisar':'Marcar para revisar'}</button><div class="actions">${questionIndex?button(icon('left',14)+' Anterior','previous-question','secondary compact'):''}${questionIndex<a.questions.length-1?button('Próxima '+icon('right',14),'next-question','compact'):button('Revisar e finalizar '+icon('check',14),'ask-finish','compact')}</div></div></section><aside class="card attempt-sidebar"><div><div class="small muted">${a.deadline?'Tempo restante':'Tempo de simulação'}</div><div class="timer" id="timer">—</div><div id="save-state" class="save-state">${icon('check',12)} Respostas salvas neste computador</div></div><div class="map-block"><h3>Seu progresso</h3><div class="question-map">${a.questions.map((question,i)=>`<button aria-label="Ir à questão ${i+1}${a.answers[question.id]?' respondida':''}${a.flags.includes(question.id)?' marcada para revisão':''}" class="${i===questionIndex?'current':''} ${a.answers[question.id]?'answered':''} ${a.flags.includes(question.id)?'flagged':''}" data-action="jump-question" data-index="${i}">${i+1}</button>`).join('')}</div><div class="legend">Preenchida: respondida<br>Ponto dourado: revisar depois<br>Contorno escuro: questão atual</div></div>${button('Finalizar tentativa','ask-finish','secondary full')}</aside></div>`;}
const duration=s=>`${Math.floor((s||0)/60)} min ${String(Math.round(s||0)%60).padStart(2,'0')} s`;
function resultPage(a){const r=a.result;const subjects=[...new Set(a.questions.filter(q=>q.type==='objective').map(q=>q.subject))];return `<a class="back-link" href="#/desempenho">${icon('left',14)} Voltar ao histórico</a>${heading('Aprender também é revisar','Sua simulação, em detalhes.','Confira o resultado, revise suas respostas e identifique o que reforçar antes da próxima tentativa.')}<div class="card"><div class="result-header"><div class="result-ring">${pct(r.accuracy)}<small>acerto objetivo</small></div><div>${statusBadge(a)}<h2>${E(a.quizName)}</h2><p>${date(a.finishedAt)} · ${E(prepName(a.prepId))}${a.isTest?' · teste administrativo':''}</p></div></div>${r.pending?notice(`${r.pending} resposta(s) discursiva(s) aguardam correção manual. A nota atual é parcial. Não há resultado final enquanto a correção estiver pendente.`):''}<div class="result-counters"><div><strong>${r.correct}</strong><span>acertos objetivos</span></div><div><strong>${r.wrong}</strong><span>erros objetivos</span></div><div><strong>${r.blank}</strong><span>objetivas em branco</span></div><div><strong>${duration(a.elapsedSeconds)}</strong><span>tempo utilizado</span></div></div><div class="grid-2"><div><h3 style="font-size:13px">Pontuação ${r.pending?'parcial':'total'}: ${r.points} / ${r.totalPoints}</h3><p class="small muted">${pct(r.weightedPercent)} dos pontos possíveis, considerando os pesos.${a.rules.passPercent!==null?' Meta configurada: '+a.rules.passPercent+'%.':' Sem meta de aprovação configurada.'}</p></div><div><p class="small muted">O acerto objetivo usa as ${r.objectiveTotal} questões objetivas aplicadas no denominador, incluindo questões sem resposta. A pontuação ponderada é um indicador separado.</p></div></div><div class="section-title"><h2>Desempenho por assunto</h2></div>${subjects.map(s=>{const qs=a.questions.filter(q=>q.type==='objective'&&q.subject===s);const right=r.subjects?.find(x=>x.subject===s)?.correct??qs.filter(q=>a.answers[q.id]===q.correct).length;return `<div class="list-row"><div class="list-main"><h3>${E(s)}</h3><p>${right} de ${qs.length} objetivas corretas</p></div><strong class="small">${pct(right/qs.length*100)}</strong></div>`;}).join('')}<div class="actions" style="margin-top:25px">${link('Praticar novamente','#/simulado/'+a.quizId,'gold')}${link('Ver meu desempenho','#/desempenho','secondary')}</div></div><div class="section-title"><h2>Revisão das respostas</h2></div><div class="card">${a.rules.review?a.questions.map((q,i)=>{const answer=a.answers[q.id],grade=a.grades[q.id];let state=q.type==='essay'?(answer?(grade?'Corrigida':'Aguardando correção'):'Sem resposta'):(answer===undefined||answer===''?'Em branco':answer===q.correct?'Correta':'Incorreta');return `<article class="review-item">${badge('Questão '+(i+1),'gray')} ${badge(state,state==='Correta'||state==='Corrigida'?'green':state==='Incorreta'?'red':'')}<h3>${E(q.prompt)}</h3><div class="answer-copy"><span class="muted">Sua resposta:</span><br>${E(q.type==='objective'?((answer!==undefined&&answer!==''?q.options[Number(answer)]:null)??'Não respondida'):(answer||'Não respondida'))}</div>${q.type==='objective'?`<p><strong>Resposta correta:</strong> ${E(q.options[Number(q.correct)])}</p><div class="explanation"><p>${E(q.explanation)}</p></div>`:`${grade?`<p><strong>Nota:</strong> ${grade.points} / ${q.points} pontos</p><div class="explanation"><p>${E(grade.feedback)}</p></div>`:`<p>${answer?'Resposta preservada. A avaliação aparecerá aqui depois da correção.':'A questão foi enviada sem resposta e não aguarda avaliação.'}</p>`}`}</article>`;}).join(''):empty('Revisão não disponibilizada.','Este simulado foi configurado sem revisão das respostas.')}</div>`;}
function performance(filter){const attempts=[...data.attempts].reverse().filter(a=>!filter||a.prepId===filter);const scored=attempts.filter(a=>a.status==='completed'&&a.result?.accuracy!==null);const mean=scored.length?scored.reduce((sum,a)=>sum+a.result.accuracy,0)/scored.length:null;const points=[...scored].reverse().slice(-10);return `${heading('Seu caminho, com clareza','Evolução se constrói na prática.','Consulte cada tentativa e encontre os assuntos que merecem uma nova revisão.')}<div class="toolbar">${prepFilter(filter)}<span class="count">${attempts.length} tentativas registradas</span></div><div class="grid-3 stats">${stat('Tentativas concluídas',scored.length,'Com correção finalizada','list')}${stat('Média objetiva',pct(mean),'Formatos podem ser diferentes','chart')}${stat('Aguardando correção',attempts.filter(a=>a.status==='awaiting_review').length,'Respostas discursivas','clock')}</div><div class="card"><div class="card-header"><div><h3>Seu histórico de acerto objetivo</h3><p>Últimas ${points.length||0} tentativas corrigidas. Cada ponto corresponde a um simulado.</p></div>${badge('Dados da sua conta','gray')}</div>${points.length?`<div class="chart-wrap"><svg viewBox="0 0 800 200" role="img" aria-label="Evolução do percentual de acerto objetivo; os valores também estão na tabela abaixo"><path d="M30 15H780M30 95H780M30 175H780" stroke="#e3e9e1" fill="none"/><text x="0" y="20" font-size="10" fill="#7d8c89">100</text><text x="7" y="100" font-size="10" fill="#7d8c89">50</text><text x="15" y="180" font-size="10" fill="#7d8c89">0</text><polyline points="${points.map((a,i)=>`${points.length===1?400:40+i*720/(points.length-1)},${175-a.result.accuracy*1.6}`).join(' ')}" stroke="#a47d40" stroke-width="2" fill="none"/>${points.map((a,i)=>`<circle cx="${points.length===1?400:40+i*720/(points.length-1)}" cy="${175-a.result.accuracy*1.6}" r="5" fill="#112d35"><title>${E(a.quizName)}: ${pct(a.result.accuracy)}</title></circle>`).join('')}</svg><div class="chart-labels"><span>Primeira tentativa exibida</span><span>Mais recente</span></div></div>`:empty('Seu histórico ainda está começando.','Finalize um simulado para visualizar a evolução.',link('Escolher simulado','#/simulados','secondary compact'))}<p class="small muted">Compare também quantidade de questões, pesos e presença de discursivas. Um mesmo percentual em simulados diferentes não indica o mesmo nível de dificuldade.</p></div><div class="section-title"><h2>Todas as tentativas</h2></div><div class="card">${attempts.length?`<div class="table-wrap"><table><thead><tr><th>Simulado / preparação</th><th>Data</th><th>Situação</th><th>Acerto objetivo</th><th>Pontos</th><th>Tempo</th><th></th></tr></thead><tbody>${attempts.map(a=>`<tr><td>${E(a.quizName)}<div class="small muted">${E(prepName(a.prepId))}${a.isTest?' · teste administrativo':''}</div></td><td>${date(a.startedAt)}</td><td>${statusBadge(a)}</td><td>${pct(a.result?.accuracy)}</td><td>${a.result?a.result.points+'/'+a.result.totalPoints:'—'}</td><td>${a.elapsedSeconds!==undefined?duration(a.elapsedSeconds):'Em curso'}</td><td><a class="btn secondary compact" href="#/tentativa/${a.id}">${a.status==='in_progress'?'Continuar':'Revisar'}</a></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma tentativa registrada.','As tentativas aparecerão aqui conforme você praticar.')}</div>`;}
function account(){if(data?.local===false)return cloudAccount(data,{heading,field,E,notice,button,link});return `${heading('Sua conta','Tudo em um só lugar.','Gerencie seus dados locais e confira a situação do seu acesso.')}<div class="account-grid"><section class="card"><h3>Dados pessoais</h3><form data-form="profile">${field('name','Nome',data.user.name,'text','required maxlength="100"')}${field('email','E-mail',data.user.email,'email','disabled')}<p class="fine" style="margin-bottom:20px">O e-mail identifica sua conta.</p><div class="form-error" role="alert"></div><button class="btn" type="submit">Salvar alterações</button></form></section><section class="card"><h3>Seu acesso</h3>${badge(data.user.hasAccess?'Acesso liberado':'Aguardando liberação',data.user.hasAccess?'green':'')}<div class="receipt"><div><span>Oferta</span><span>Todos os conteúdos publicados</span></div><div><span>Preço planejado</span><span>R$ 29,90 · pagamento único</span></div><div><span>Mensalidade</span><span>Não há</span></div><div><span>Validade da oferta</span><span>Vitalícia</span></div></div>${notice('Esta conta e todos os pagamentos são locais. Não há conexão com um cadastro ou compra de produção.')}<div class="actions" style="margin-top:22px">${button('Ver pagamentos locais','my-orders','secondary compact')}${button('Sair','logout','secondary compact')}</div></section></div>`;}
async function checkout(){if(data?.local===false)return cloudCheckout(data,{bar,brand,link,notice});if(!data.user)return `${header()}<main class="public-wrap checkout" id="main">${heading('Acesso vitalício','Seu próximo simulado começa aqui.','Entre ou crie uma conta antes de continuar para a simulação de compra.')}<div class="grid-2"><div class="card">${notice('Esta é uma demonstração local. Nenhum valor será cobrado.')}<div class="actions" style="margin-top:25px">${link('Criar minha conta','#/cadastro','gold')}${link('Já tenho uma conta','#/entrar','secondary')}</div></div><div class="checkout-summary"><h3>Todos os conteúdos da oferta</h3><div class="checkout-price">R$ 29,90</div><p>Pagamento único. Acesso vitalício.</p></div></div></main>`;const orders=await api('/orders'),last=orders.at(-1);return `${header()}<main class="public-wrap checkout" id="main"><a class="back-link" href="#/">${icon('left',14)} Voltar</a><div class="eyebrow">Um espaço para ir mais longe</div><h1>Seu acesso, sem complicação.</h1><div class="checkout-grid"><section class="card checkout-card"><h2>${data.user.hasAccess?'Está tudo pronto para simular.':'Valide a experiência de compra.'}</h2>${notice('SIMULAÇÃO LOCAL. Nenhum dado de cartão é solicitado e nenhum valor será cobrado.')}<div class="receipt"><div><span class="muted">Sua conta</span><strong>${E(data.user.name)}</strong></div><div><span class="muted">E-mail</span><span>${E(data.user.email)}</span></div><div><span class="muted">Oferta única</span><span>R$ 29,90 · BRL</span></div></div>${data.user.hasAccess?`<div class="checkout-state">${badge('Acesso liberado','green')}<h3>Todos os simulados publicados, na sua conta.</h3><p class="small muted">Você não precisa comprar separadamente outra certificação incluída nesta oferta.</p></div>${link('Ir para minha área '+icon('arrow',16),'#/inicio','gold full')}`:last?.status==='pending'?`<div class="checkout-state">${badge('Pagamento pendente')}<h3>Aguardando confirmação simulada.</h3><p class="small muted">A página de sucesso, sozinha, não libera o conteúdo. Use um evento de teste abaixo para validar a confirmação no servidor local.</p></div><div class="stack">${button('Simular confirmação do pagamento','confirm-payment','gold full')}${button('Simular pagamento recusado','decline-payment','secondary full')}</div>`:last?.status==='declined'?`<div class="checkout-state">${badge('Pagamento recusado','red')}<h3>O acesso continua bloqueado.</h3><p class="small muted">Nenhuma cobrança real foi realizada. Você pode iniciar outra simulação.</p></div>${button('Tentar novamente','create-order','gold full')}`:`<p class="description">Uma única compra libera os simulados e materiais de apoio publicados, incluindo novos conteúdos adicionados à mesma oferta.</p>${button('Iniciar compra de demonstração '+icon('arrow',16),'create-order','gold full')}`}<p class="fine">Suporte, identificação do responsável e política de reembolso precisam ser definidos antes de operar comercialmente.</p></section><aside class="checkout-summary"><div class="eyebrow" style="color:#d2b77e">A oferta completa</div><h3>Sua área de simulação.</h3><div class="checkout-price">R$ 29,90</div><p>Pagamento único. Acesso vitalício.<br>Sem mensalidade ou renovação paga.</p><ul class="check-list">${['Simulados por prova ou certificação','Revisão das respostas e materiais de apoio','Histórico e indicadores de desempenho','Novos conteúdos da mesma oferta'].map(t=>`<li>${icon('check',16)}${t}</li>`).join('')}</ul><p class="small">A inscrição no exame oficial não está incluída. A prévia contém exemplos demonstrativos, não uma preparação pronta para venda.</p></aside></div></main>`;}
const adminTabs=[['visao-geral','Visão geral'],['preparacoes','Preparações'],['materiais','Materiais'],['questoes','Questões'],['simulados','Simulados'],['correcoes','Correções'],['alunos','Alunos'],['pagamentos','Pagamentos'],['conteudo','Conteúdo a enviar']];
function admin(section='visao-geral'){const d=adminData,studentAttempts=d.attempts.filter(a=>!a.isTest),paid=d.orders.filter(o=>o.status==='paid');let content='';if(section==='visao-geral'&&data.local===false)content=cloudAdminOverview(d,{stat,link,notice});else if(section==='pagamentos'&&data.local===false)content=cloudPayments({notice,link});else if(section==='visao-geral')content=`<div class="grid-3 stats">${stat('Contas locais de alunos',d.users.filter(u=>u.role==='student').length,'Inclui o perfil demonstrativo','user')}${stat('Tentativas de alunos',studentAttempts.length,'Testes administrativos separados','list')}${stat('Volume pago simulado',money(paid.reduce((s,o)=>s+o.amount,0)),'Não representa receita real','chart')}</div><div class="grid-2"><div class="card"><h3>Pronto para você validar</h3><ul class="check-list">${['Cadastro, login e recuperação local','Compra pendente, recusada e confirmada','Materiais, simulados e rascunhos salvos','Objetivas, discursivas e histórico imutável'].map(s=>`<li>${icon('check',16)}${s}</li>`).join('')}</ul></div><div class="card"><h3>Antes de publicar</h3><p class="description">Revisão editorial, cadastro empresarial, suporte, termos, provedor de pagamentos e integração de autenticação precisam ser concluídos na etapa de produção.</p>${notice('Este painel é uma demonstração local. A entrada de perfil master não é um mecanismo de autorização para produção.')}</div></div><div class="section-title"><h2>Correções aguardando você</h2>${link('Abrir correções','#/admin/correcoes','secondary compact')}</div><div class="card">${d.pending.length?d.pending.map(a=>`<div class="list-row"><div class="list-main"><h3>${E(a.quizName)}</h3><p>${E(d.users.find(u=>u.id===a.userId)?.name)} · ${a.result.pending} resposta(s)${a.isTest?' · teste administrativo':''}</p></div>${link('Corrigir','#/admin/correcoes','secondary compact')}</div>`).join(''):empty('Nenhuma correção pendente.','Envie uma resposta no simulado misto para validar este fluxo.')}</div><div class="section-title"><h2>Testes administrativos</h2></div><div class="card"><p class="small muted">${d.attempts.filter(a=>a.isTest).length} tentativas de teste separadas dos indicadores de alunos.</p>${link('Abrir simulados como master','#/simulados','secondary compact')}</div>`;
 if(section==='preparacoes')content=adminList('Preparações','Crie e organize a navegação por certificação.','preparations',d.preparations,p=>`<h3>${E(p.name)} ${badge(p.status==='published'?'Publicada':'Em preparação',p.status==='published'?'green':'gray')}</h3><p>${E(p.description)}</p>`);
 if(section==='materiais')content=adminList('Materiais','Organize por preparação e módulo. Publique somente conteúdos revisados.','materials',d.materials,m=>`<h3>${E(m.title)} ${badge(m.status==='published'?'Publicado':'Rascunho',m.status==='published'?'green':'gray')}</h3><p>${E(prepName(m.prepId))} · ${E(m.module)} · ${m.format==='link'?'Link HTTPS':'Texto'}</p>`);
 if(section==='questoes')content=adminList('Banco de questões','As alterações se aplicam às próximas tentativas; históricos preservam a versão usada.','questions',d.questions,q=>`<h3>${E(q.prompt)}</h3><p>${E(prepName(q.prepId))} · ${E(q.subject)} · ${q.type==='essay'?'Discursiva':'Objetiva'} · ${q.points} ponto(s)</p>`);
 if(section==='simulados')content=adminList('Simulados','Configure questões, duração, pesos, aprovação e novas tentativas.','quizzes',d.quizzes,q=>`<h3>${E(q.name)} ${badge(q.status==='published'?'Publicado':'Rascunho',q.status==='published'?'green':'gray')}</h3><p>${E(prepName(q.prepId))} · ${q.questionIds.length} questões · ${q.durationMinutes?q.durationMinutes+' min':'Sem cronômetro'} · ${q.passPercent===null?'Sem meta':q.passPercent+'% de meta'}</p>`);
 if(section==='correcoes')content=`<div class="admin-heading"><div><h2>Correções discursivas</h2><p>Notas e feedbacks fazem parte do histórico da tentativa.</p></div></div><div class="stack">${d.pending.map(a=>`<div class="card"><div class="card-header"><div><h3>${E(a.quizName)}</h3><p>${E(d.users.find(u=>u.id===a.userId)?.name)} · ${date(a.startedAt)}${a.isTest?' · teste administrativo':''}</p></div>${badge('Aguardando correção')}</div>${a.questions.filter(q=>q.type==='essay'&&a.answers[q.id]&&!a.grades[q.id]).map(q=>`<article class="review-item"><h3>${E(q.prompt)}</h3><div class="answer-copy">${E(a.answers[q.id])}</div><p><strong>Critério:</strong> ${E(q.rubric)}</p><p style="margin-top:8px"><strong>Referência:</strong> ${E(q.explanation)}</p><form data-form="grade" data-attempt="${a.id}" data-question="${q.id}" style="margin-top:20px">${field('points',`Nota (0 a ${q.points})`,'','number',`required min="0" max="${q.points}" step="0.1"`)}${area('feedback','Feedback para o aluno','','required maxlength="3000"')}<div class="form-error" role="alert"></div><button class="btn compact" type="submit">Salvar correção</button></form></article>`).join('')}</div>`).join('')||`<div class="card">${empty('Tudo revisado por aqui.','Não há respostas discursivas aguardando correção.')}</div>`}</div>`;
 if(section==='alunos')content=`<div class="admin-heading"><div><h2>Alunos e acessos</h2><p>Liberações manuais abaixo valem somente na sua conta.</p></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Conta</th><th>Perfil</th><th>Acesso</th><th></th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${E(u.name)}<div class="small muted">${E(u.email)}</div></td><td>${badge(u.role==='master'?'Master':u.demo?'Aluno de demonstração':'Aluno','gray')}</td><td>${badge(u.hasAccess?'Liberado':'Pendente',u.hasAccess?'green':'')}</td><td>${u.role!=='master'?`<button class="btn secondary compact" data-action="toggle-access" data-id="${u.id}" data-active="${!u.manualAccess}">${u.manualAccess?'Remover liberação manual':'Liberar manualmente'}</button>`:''}</td></tr>`).join('')}</tbody></table></div><p class="fine">Remover liberação manual não revoga uma compra já confirmada. Perfis de alunos não podem alterar permissões pela API.</p></div>`;
 if(section==='pagamentos')content=`<div class="admin-heading"><div><h2>Pagamentos simulados</h2><p>Registros exclusivamente locais, sem movimentação financeira.</p></div></div><div class="card">${d.orders.length?`<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Data</th><th>Valor</th><th>Situação</th><th>Origem</th></tr></thead><tbody>${[...d.orders].reverse().map(o=>`<tr><td>${E(d.users.find(u=>u.id===o.userId)?.name)}</td><td>${date(o.createdAt)}</td><td>${money(o.amount)}</td><td>${badge(o.status==='paid'?'Confirmado':o.status==='declined'?'Recusado':'Pendente',o.status==='paid'?'green':o.status==='declined'?'red':'')}</td><td>${badge('Simulação local','gray')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum pagamento simulado.','Crie uma conta e valide o checkout de demonstração.')}</div>`;
 if(section==='conteudo')content=contentChecklist();
 return `${heading('Administração','Um espaço bem cuidado.','Organize os conteúdos, acompanhe acessos e revise o aprendizado.',badge('Perfil master de demonstração'))}<nav class="admin-tabs" aria-label="Seções administrativas">${adminTabs.map(([r,t])=>`<a class="${section===r?'active':''}" href="#/admin/${r}">${t}${r==='correcoes'&&d.pending.length?' ('+d.pending.length+')':''}</a>`).join('')}</nav>${content}`;
}
function adminList(title,desc,type,items,body){return `<div class="admin-heading"><div><h2>${title}</h2><p>${desc}</p></div><button class="btn compact" data-action="edit-item" data-type="${type}">${icon('plus',15)} Adicionar</button></div><div class="card">${items.map(item=>`<div class="admin-row"><div>${body(item)}</div><div class="actions"><button class="btn secondary compact" data-action="edit-item" data-type="${type}" data-id="${item.id}">${icon('edit',13)} Editar</button>${item.status?`<button class="btn secondary compact" data-action="toggle-publish" data-type="${type}" data-id="${item.id}">${item.status==='published'?'Despublicar':'Publicar'}</button>`:''}</div></div>`).join('')||empty('Ainda não há registros.','Use o botão Adicionar para criar o primeiro.')}</div>`;}
function showModal(title,body,footer=''){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar">${icon('close',20)}</button></header>${body}${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;requestAnimationFrame(()=>$('.modal input,.modal textarea,.modal select,.modal button')?.focus());}
function closeModal(){$('#modal-root').innerHTML='';lastFocus?.focus?.();}
function editor(type,id){const item=adminData[type].find(x=>x.id===id)||{};let content='';if(type==='preparations')content=field('name','Nome da preparação',item.name||'','text','required')+area('description','Descrição',item.description||'','required');
 if(type==='materials')content=select('prepId','Preparação',prepOptions(),item.prepId||'ancord')+field('module','Módulo ou assunto',item.module||'','text','required')+field('title','Título',item.title||'','text','required')+select('format','Formato',[['text','Aula em texto'],['link','Link HTTPS autorizado']],item.format||'text')+area('body','Conteúdo ou endereço HTTPS',item.body||'','required style="min-height:190px"');
 if(type==='questions')content=select('prepId','Preparação',prepOptions(),item.prepId||'ancord')+field('subject','Assunto',item.subject||'','text','required')+area('prompt','Enunciado',item.prompt||'','required')+`<div class="field-row">${select('type','Tipo',[['objective','Objetiva'],['essay','Discursiva']],item.type||'objective')}${field('points','Pontuação',item.points??1,'number','required min="0.1" max="100" step="0.1"')}</div><div id="objective-fields" ${item.type==='essay'?'hidden':''}>${area('options','Alternativas (uma por linha)',item.options?.join('\n')||'','')}<div class="field"><label for="f-correct">Número da alternativa correta</label><input id="f-correct" type="number" name="correct" min="1" max="8" value="${item.correct!==null&&item.correct!==undefined?Number(item.correct)+1:1}"><small>Por exemplo: 1 para a primeira alternativa.</small></div></div><div id="essay-fields" ${item.type!=='essay'?'hidden':''}>${area('rubric','Critério de correção',item.rubric||'')}</div>${area('explanation','Explicação ou resposta de referência',item.explanation||'','required')}`;
 if(type==='quizzes')content=select('prepId','Preparação',prepOptions(),item.prepId||'ancord')+field('name','Nome do simulado',item.name||'','text','required')+area('description','Descrição',item.description||'')+`<div class="field-row">${field('durationMinutes','Duração em minutos',item.durationMinutes??'','number','min="1" max="1440" placeholder="Sem limite"')}${field('passPercent','Meta de pontuação (%)',item.passPercent??'','number','min="0" max="100" step="0.1" placeholder="Sem meta"')}</div>${field('maxAttempts','Limite de tentativas',item.maxAttempts??'','number','min="1" placeholder="Sem limite"')}<div class="field"><span>Questões do simulado</span><div class="question-pick" id="question-pick">${questionPick(item.prepId||'ancord',item.questionIds||[])}</div><small>Os pesos de cada questão são definidos no banco de questões.</small></div>${select('review','Disponibilizar revisão',[['true','Sim, após finalizar'],['false','Não disponibilizar']],String(item.review!==false))}`;
 if(type!=='questions')content+=select('status','Situação',[['draft',type==='preparations'?'Em preparação':'Rascunho'],['published','Publicado']],item.status||'draft');const titles={preparations:'preparação',materials:'material',questions:'questão',quizzes:'simulado'};showModal(`${id?'Editar':'Adicionar'} ${titles[type]}`,`<form data-form="admin-editor" data-type="${type}" data-id="${id||''}">${content}<div class="form-error" role="alert"></div><div class="modal-footer">${button('Cancelar','close-modal','secondary')}<button class="btn" type="submit">Salvar ${titles[type]}</button></div></form>`);}
function questionPick(prep,selected=[]){return adminData.questions.filter(q=>q.prepId===prep).map(q=>`<label><input type="checkbox" name="questionIds" value="${q.id}" ${selected.includes(q.id)?'checked':''}><span>${E(q.prompt)}<br><span class="muted">${q.type==='essay'?'Discursiva':'Objetiva'} · ${q.points} ponto(s)</span></span></label>`).join('')||'<p class="small muted">Cadastre uma questão nesta preparação primeiro.</p>';}
let workspaceData=null,activeNote=null,focusState=null,focusOwner='';
const localDay=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const showDay=d=>d?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(d+'T12:00:00')):'Sem data';
const taskKind={simulation:'Simulado',review:'Revisão',material:'Material de apoio',free:'Atividade pessoal'};
function weekStart(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d;}
function personalDashboard(){
  const w=workspaceData,first=data.user.name.split(' ')[0],ongoing=data.attempts.find(a=>a.status==='in_progress'),finished=data.attempts.filter(a=>a.status==='completed'),due=w.tasks.filter(t=>!t.completed&&t.dueDate<=localDay()),pendingReview=w.reviewItems.filter(i=>!i.reviewedAt),week=weekStart(),weekDone=finished.filter(a=>new Date(a.finishedAt)>=week).length,goal=w.preferences.weeklyGoal,focusMinutes=w.focusSessions.filter(s=>new Date(s.createdAt)>=week).reduce((n,s)=>n+s.minutes,0);
  const objective=w.preferences.prepId?prepName(w.preferences.prepId):'Escolha uma prova para orientar sua prática';
  return `${heading('Meu painel pessoal',`Olá, ${E(first)}. Qual é o próximo passo?`,'Seus simulados, anotações e revisões, organizados em um espaço só.',button(icon('target',15)+' Meu objetivo','ws-goal','secondary compact'))}
  <div class="workspace-overview"><section class="card dark continue-card"><div>${badge(data.user.hasAccess?(ongoing?'Tentativa em andamento':'Seu próximo simulado'):'Seu painel já está disponível','outline')}<h2>${data.user.hasAccess?(ongoing?E(ongoing.quizName):'Uma nova tentativa. Mais clareza para avançar.'):'Organize sua prática. Ative os simulados quando quiser.'}</h2><p>${data.user.hasAccess?(ongoing?'Retome suas respostas salvas. Cada tentativa continua separada no histórico.':'Escolha um simulado, responda e volte à revisão. Você pode repetir os disponíveis conforme as regras de cada um.'):'Use as anotações, o plano e o temporizador. Os simulados e materiais são liberados após a confirmação da compra simulada.'}</p>${link(data.user.hasAccess?(ongoing?'Continuar tentativa '+icon('arrow',15):'Escolher simulado '+icon('arrow',15)):'Ativar acesso · R$ 29,90',data.user.hasAccess?(ongoing?'#/tentativa/'+ongoing.id:'#/simulados'):'#/checkout','gold')}</div></section>
  <section class="card workspace-week"><div class="eyebrow">Sua meta pessoal da semana</div><div class="workspace-week-count">${weekDone}<span>/ ${goal}</span></div><p>simulados concluídos</p><div class="progress"><span style="width:${Math.min(100,weekDone/goal*100)}%"></span></div><div class="small muted" style="margin-top:18px">${E(objective)}${w.preferences.examDate?'<br>Data planejada: '+showDay(w.preferences.examDate):''}</div></section></div>
  <div class="workspace-tools">${[['anotacoes','file','Anotações',w.notes.length+' notas pessoais','Registre dúvidas e o que aprendeu.'],['plano','clock','Meu plano',due.length+' atividades para retomar','Distribua sua prática ao longo dos dias.'],['revisao','flag','Caderno de erros',pendingReview.length+' questões para revisar','Reveja erros e questões em branco.'],['foco','target','Modo foco',focusMinutes+' min registrados na semana','Reserve um bloco para praticar.']].map(([r,i,t,n,p])=>`<a class="card workspace-tool" href="#/${r}"><div class="workspace-tool-icon">${icon(i,22)}</div><span>${icon('arrow',15)}</span><h3>${t}</h3><p>${p}</p><strong>${n}</strong></a>`).join('')}</div>
  <div class="grid-2"><section class="card"><div class="card-header"><div><h3>Hoje e pendências</h3><p>Atividades que você escolheu para sua rotina.</p></div><a class="btn text" href="#/plano">Ver plano ${icon('right',13)}</a></div>${due.length?due.sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,4).map(taskRow).join(''):empty('Seu próximo bloco ainda está em aberto.','Agende um simulado, uma revisão ou outra atividade.',button('Planejar uma atividade','ws-new-task','secondary compact'))}</section><section class="card"><div class="card-header"><div><h3>Últimas tentativas</h3><p>Uma mesma prova pode ter vários simulados e tentativas.</p></div><a class="btn text" href="#/desempenho">Histórico ${icon('right',13)}</a></div>${data.attempts.length?attemptRows([...data.attempts].reverse().slice(0,4)):empty('Seu histórico começa na primeira tentativa.','Os resultados mostrados aqui serão os da sua própria conta.',link('Explorar simulados','#/simulados','secondary compact'))}</section></div>
  <div class="section-title"><h2>Pratique com método</h2></div><section class="card workspace-method"><div>${icon('list',22)}<h3>Responda antes de consultar</h3><p>Use o simulado para tentar recuperar o que sabe, em vez de apenas reconhecer a resposta.</p></div><div>${icon('check',22)}<h3>Reveja e explique o erro</h3><p>Depois da correção, registre com suas palavras o raciocínio que precisa retomar.</p></div><div>${icon('clock',22)}<h3>Volte em outros dias</h3><p>Distribua as sessões no seu plano pessoal. Não há um intervalo universal garantido para passar.</p></div><p class="workspace-method-source">Prática com testes e prática distribuída são técnicas apoiadas pela revisão de <a href="https://www.psychologicalscience.org/publications/journals/pspi/learning-techniques.html" target="_blank" rel="noopener noreferrer">Dunlosky et al. (2013)</a>. As ferramentas organizam a rotina; não garantem aprovação.</p></section>`;
}
function noteDraftKey(id='new'){return 'simulou-nota:'+data.user.id+':'+id;}
function notesPage(){
  const r=route(),notes=[...workspaceData.notes].sort((a,b)=>Number(b.favorite)-Number(a.favorite)||b.updatedAt.localeCompare(a.updatedAt)),id=r.query.get('nota');
  if(id&&!notes.some(n=>n.id===id))return empty('Anotação não encontrada.','Esta anotação não está disponível na sua conta.',link('Voltar às anotações','#/anotacoes'));
  const selected=id?notes.find(n=>n.id===id):r.query.has('nova')?null:notes[0];activeNote=selected?{...selected}:{id:null,title:'',body:'',prepId:'',favorite:false};
  let restored=false;try{const cached=JSON.parse(localStorage.getItem(noteDraftKey(activeNote.id||'new'))||'null');if(cached?.pending){activeNote={...activeNote,...cached.values,id:activeNote.id};restored=true;}}catch{}
  return `${heading('Seu bloco pessoal','Anotações que ficam com você.','Guarde dúvidas, fórmulas e aprendizados. Somente sua conta acessa estas notas.',link(icon('plus',15)+' Nova anotação','#/anotacoes?nova=1','compact'))}<div class="notes-layout"><aside class="card notes-list"><div class="field"><label class="screen-reader" for="note-search">Buscar anotações</label><input id="note-search" type="search" placeholder="Buscar nas suas anotações…"></div><div class="small muted" style="margin-bottom:16px">${notes.length} ${notes.length===1?'anotação salva':'anotações salvas'}</div>${notes.map(n=>`<a class="note-list-item ${n.id===activeNote.id?'active':''}" data-note-search="${E((n.title+' '+n.body+' '+prepName(n.prepId)).toLowerCase())}" href="#/anotacoes?nota=${n.id}"><div class="actions"><strong>${E(n.title)}</strong>${n.favorite?icon('flag',12):''}</div><p>${E(n.body.slice(0,95))}</p><small>${n.prepId?E(prepName(n.prepId))+' · ':''}${date(n.updatedAt)}</small></a>`).join('')||'<p class="small muted">Sua primeira anotação pode começar com uma dúvida do próximo simulado.</p>'}</aside><section class="card note-editor"><form data-form="workspace-note" data-note-id="${activeNote.id||''}"><div class="note-editor-top"><span>${badge(activeNote.id?'Nota pessoal':'Nova anotação','gray')}</span><div class="actions">${activeNote.id?`<button class="icon-btn" type="button" data-action="ws-delete-note" data-id="${activeNote.id}" aria-label="Excluir anotação">${icon('close',17)}</button>`:''}<button type="submit" class="btn compact">${icon('check',15)} Salvar anotação</button></div></div>${field('title','Título',activeNote.title,'text','maxlength="160" data-note-input placeholder="Qual ideia você quer guardar?"')}${select('prepId','Prova ou certificação (opcional)',[['','Sem vínculo'],...prepOptions()],activeNote.prepId)}${area('body','Sua anotação',activeNote.body,'required maxlength="30000" data-note-input placeholder="O que eu errei? Qual é o raciocínio correto? O que preciso lembrar na próxima tentativa?" class="note-body"')}<label class="check-inline"><input type="checkbox" name="favorite" ${activeNote.favorite?'checked':''} data-note-input> Fixar esta anotação</label><div id="note-draft-state" class="small muted" role="status">${restored?'Rascunho recuperado deste navegador. Salve para registrar na conta.':activeNote.id?'Salva na conta em '+date(activeNote.updatedAt):'O rascunho é preservado neste navegador. Use Salvar para guardar na conta.'}</div>${activeNote.sourceAttemptId?`<a class="back-link" style="margin:18px 0 0" href="#/tentativa/${E(activeNote.sourceAttemptId)}">${icon('left',13)} Ver tentativa vinculada</a>`:''}<div class="form-error" role="alert"></div></form></section></div>`;
}
function saveLocalNoteDraft(){const form=$('[data-form="workspace-note"]');if(!form)return;const values=Object.fromEntries(new FormData(form));values.favorite=!!$('[name="favorite"]',form).checked;values.sourceAttemptId=activeNote?.sourceAttemptId||null;values.sourceQuestionId=activeNote?.sourceQuestionId||null;try{localStorage.setItem(noteDraftKey(form.dataset.noteId||'new'),JSON.stringify({pending:true,values}));$('#note-draft-state').textContent='Rascunho neste navegador · ainda não salvo na conta.';}catch{$('#note-draft-state').textContent='Não foi possível guardar o rascunho neste navegador. Salve na conta.';}}
function taskRow(t){return `<div class="task-row ${t.completed?'done':''}"><button class="task-check" data-action="ws-toggle-task" data-id="${t.id}" aria-label="${t.completed?'Reabrir':'Concluir'} ${E(t.title)}">${t.completed?icon('check',14):''}</button><div class="list-main"><h3>${E(t.title)}</h3><p>${taskKind[t.kind]}${t.prepId?' · '+E(prepName(t.prepId)):''} · ${showDay(t.dueDate)} ${!t.completed&&t.dueDate<localDay()?badge('Pendente') : ''}</p></div>${t.quizId&&!t.completed?link('Simular','#/simulado/'+t.quizId,'secondary compact'):''}<button class="icon-btn" data-action="ws-edit-task" data-id="${t.id}" aria-label="Editar ${E(t.title)}">${icon('edit',14)}</button></div>`;}
function planPage(){const tasks=[...workspaceData.tasks].sort((a,b)=>Number(a.completed)-Number(b.completed)||a.dueDate.localeCompare(b.dueDate)),week=weekStart();return `${heading('Meu plano de prática','Uma rotina que cabe no seu dia.','Escolha quando simular, revisar e retomar os materiais. Os horários são definidos por você.',button(icon('plus',15)+' Adicionar atividade','ws-new-task','compact'))}<div class="week-calendar">${Array.from({length:7},(_,i)=>{const d=new Date(week);d.setDate(d.getDate()+i);const day=localDay(d),list=tasks.filter(t=>t.dueDate===day);return `<div class="week-day ${day===localDay()?'today':''}"><span>${new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(d)}</span><strong>${d.getDate()}</strong><small>${list.length} ${list.length===1?'atividade':'atividades'}</small><div class="week-dots">${list.slice(0,5).map(t=>`<i class="${t.completed?'done':''}"></i>`).join('')}</div></div>`;}).join('')}</div><div class="grid-2"><div class="card"><div class="card-header"><div><h3>Próximas atividades e pendências</h3><p>Marcar como concluída não altera o resultado de um simulado.</p></div>${button('Meu objetivo','ws-goal','text')}</div>${tasks.filter(t=>!t.completed).map(taskRow).join('')||empty('Seu plano está livre.','Adicione sua próxima simulação ou uma revisão.',button('Planejar atividade','ws-new-task','secondary compact'))}</div><div class="card"><div class="card-header"><div><h3>Atividades concluídas</h3><p>Seu registro pessoal de prática.</p></div>${icon('check',17)}</div>${tasks.filter(t=>t.completed).map(taskRow).join('')||empty('Uma atividade por vez.','As atividades concluídas aparecerão aqui.')}</div></div><p class="inline-note">Distribuir a prática em mais de uma sessão é uma estratégia apoiada pela pesquisa. As datas deste plano são escolhas pessoais, sem intervalo obrigatório ou promessa de aprovação.</p>`;}
function taskEditor(id){const t=workspaceData.tasks.find(t=>t.id===id)||{title:'',kind:'simulation',prepId:workspaceData.preferences.prepId||'',dueDate:localDay(),quizId:''};const options=data.quizzes.filter(q=>!t.prepId||q.prepId===t.prepId);showModal(id?'Editar atividade':'Planejar uma atividade',`<form data-form="workspace-task" data-id="${id||''}">${field('title','Atividade',t.title,'text','required maxlength="180" placeholder="Ex.: Simulado de renda fixa e revisão dos erros"')}<div class="field-row">${select('kind','Tipo',Object.entries(taskKind),t.kind)}${field('dueDate','Data',t.dueDate,'date','required')}</div>${select('prepId','Prova ou certificação',[['','Sem vínculo'],...prepOptions()],t.prepId)}<div id="task-quiz-field" ${t.kind!=='simulation'?'hidden':''}>${select('quizId','Vincular simulado (opcional)',[['','Escolher depois'],...options.map(q=>[q.id,q.name])],t.quizId)}</div><div class="form-error" role="alert"></div><div class="modal-footer">${id?`<button class="btn secondary" type="button" data-action="ws-delete-task" data-id="${id}">Excluir atividade</button>`:button('Cancelar','close-modal','secondary')}<button class="btn" type="submit">Salvar atividade</button></div></form>`);}
function goalEditor(){const p=workspaceData.preferences;showModal('Seu objetivo de prática',`<form data-form="workspace-goal">${select('prepId','Prova ou certificação',[['','Ainda não escolhi'],...prepOptions()],p.prepId)}${field('examDate','Data planejada da prova (opcional)',p.examDate,'date')}${field('weeklyGoal','Minha meta de simulados por semana',p.weeklyGoal,'number','required min="1" max="30" step="1"')}<p class="small muted">Esta é uma meta pessoal para organizar sua rotina. Não é uma quantidade científica necessária para aprovação.</p><div class="form-error" role="alert"></div><div class="modal-footer">${button('Cancelar','close-modal','secondary')}<button class="btn" type="submit">Salvar objetivo</button></div></form>`);}
function reviewPage(){const r=route(),filter=r.query.get('prep')||'',status=r.query.get('situacao')||'pending',items=workspaceData.reviewItems.filter(i=>(!filter||i.prepId===filter)&&(status==='all'||(status==='reviewed'?i.reviewedAt:!i.reviewedAt)));return `${heading('Caderno de erros','O erro vira seu próximo assunto.','Questões objetivas incorretas ou em branco das suas tentativas finalizadas, quando a revisão estiver liberada.')}<div class="toolbar">${prepFilter(filter)}<select class="filter-select" id="review-status" aria-label="Situação da revisão"><option value="pending" ${status==='pending'?'selected':''}>Para revisar</option><option value="reviewed" ${status==='reviewed'?'selected':''}>Revisadas</option><option value="all" ${status==='all'?'selected':''}>Todas</option></select><span class="count">${items.length} questões nesta seleção</span></div><div class="stack">${items.map(i=>`<article class="card review-notebook-item"><div class="actions">${badge(prepName(i.prepId),'gray')}${badge(i.subject,'gray')}<span class="spacer"></span>${badge(i.reviewedAt?'Revisada':i.answer===null||i.answer===''?'Em branco':'Resposta incorreta',i.reviewedAt?'green':'')}</div><h3>${E(i.prompt)}</h3><div class="review-answer-grid"><div><span>Sua resposta</span><p>${E(i.answer===null||i.answer===''?'Não respondida':i.options[Number(i.answer)])}</p></div><div><span>Resposta correta</span><p>${E(i.options[Number(i.correct)])}</p></div></div><div class="explanation"><p>${E(i.explanation)}</p></div><p class="small muted" style="margin:16px 0">${E(i.quizName)} · ${date(i.finishedAt)}</p><div class="actions"><button class="btn secondary compact" data-action="ws-note-review" data-id="${E(i.id)}">${icon('file',14)} Criar anotação</button><button class="btn secondary compact" data-action="ws-review-task" data-id="${E(i.id)}">${icon('clock',14)} Agendar revisão</button><span class="spacer"></span><button class="btn compact ${i.reviewedAt?'secondary':''}" data-action="ws-review-toggle" data-id="${E(i.id)}">${icon('check',14)} ${i.reviewedAt?'Reabrir revisão':'Marcar como revisada'}</button></div></article>`).join('')||`<div class="card">${empty('Nenhuma questão nesta seleção.','Finalize um simulado para construir seu caderno ou consulte as revisões já concluídas.',link('Abrir simulados','#/simulados','secondary compact'))}</div>`}</div><p class="inline-note">Cada item preserva a versão da tentativa original. Marcar como revisada é uma organização pessoal e não modifica a nota do simulado.</p>`;}
function defaultFocus(minutes=25,topic=''){return {minutes,topic,remainingMs:minutes*60000,running:false,deadline:null,startedAt:null,eventId:null};}
function ensureFocus(){if(focusOwner===data.user.id&&focusState)return;focusOwner=data.user.id;try{focusState=JSON.parse(localStorage.getItem('simulou-foco:'+focusOwner)||'null');}catch{}if(!focusState||!Number.isFinite(focusState.remainingMs)||focusState.remainingMs<0||focusState.minutes<1||focusState.minutes>180)focusState=defaultFocus();}
function remainingFocus(){return focusState.running?Math.max(0,focusState.deadline-Date.now()):focusState.remainingMs;}
function persistFocus(){try{localStorage.setItem('simulou-foco:'+focusOwner,JSON.stringify(focusState));}catch{}}
function pauseFocus(){if(!focusState?.running)return;focusState.remainingMs=remainingFocus();focusState.running=false;focusState.deadline=null;persistFocus();}
function focusPage(){ensureFocus();if(focusState.running&&remainingFocus()===0)pauseFocus();const started=!!focusState.startedAt,remaining=remainingFocus(),finished=started&&remaining===0;return `${heading('Modo foco','Um bloco para sua próxima conquista.','Use o temporizador para reservar um período de prática ou revisão. A duração é sua escolha.')}<div class="focus-layout"><section class="card focus-main"><div class="eyebrow">${finished?'Bloco concluído':focusState.running?'Seu bloco está em andamento':started?'Temporizador pausado':'Prepare seu bloco'}</div><div id="focus-clock" class="focus-clock" role="timer" aria-label="Tempo restante">${Math.ceil(remaining/60000).toString().padStart(2,'0')}:00</div><div class="focus-settings">${field('focusMinutes','Duração do bloco (minutos)',focusState.minutes,'number',`min="1" max="180" ${started?'disabled':''}`)}${field('focusTopic','Assunto deste bloco',focusState.topic,'text',`maxlength="160" placeholder="Ex.: Revisar os erros de renda fixa" ${started?'disabled':''}`)}</div><div class="actions focus-actions">${!finished?button(icon(focusState.running?'clock':'target',16)+(focusState.running?' Pausar':started?' Continuar bloco':' Iniciar bloco'),focusState.running?'ws-focus-pause':'ws-focus-start','gold'):''}${started?button('Registrar tempo e encerrar','ws-focus-record','secondary'):''}${button(started?'Reiniciar':'Restaurar 25 minutos','ws-focus-reset','text')}</div><p class="small muted">O relógio continua ao navegar entre as páginas enquanto esta aplicação estiver aberta. Pausas não contam. Um bloco só entra no histórico quando você escolhe registrá-lo.</p></section><aside class="card"><div class="card-header"><div><h3>Seus blocos registrados</h3><p>Registros pessoais, sem avaliação automática de aprendizado.</p></div>${icon('clock',18)}</div>${workspaceData.focusSessions.length?workspaceData.focusSessions.slice(0,8).map(s=>`<div class="list-row"><div class="list-main"><h3>${E(s.topic)}</h3><p>${date(s.createdAt)}</p></div><strong class="small">${s.minutes} min</strong></div>`).join(''):empty('Seu primeiro bloco pode ser hoje.','Ao terminar, registre o tempo para acompanhar sua rotina.')}</aside></div>`;}
function workspaceTick(){if(!data?.user||focusOwner!==data.user.id||!focusState)return;const el=$('#focus-clock');if(!el)return;const remaining=remainingFocus(),seconds=Math.ceil(remaining/1000);el.textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(focusState.running&&remaining===0){pauseFocus();toast('Bloco concluído. Você pode registrar o tempo no modo foco.');if(route().parts[0]==='foco')render();}}
async function workspaceAction(name,el){
 if(name==='ws-goal'){goalEditor();return;}if(name==='ws-new-task'){taskEditor();return;}if(name==='ws-edit-task'){taskEditor(el.dataset.id);return;}
 if(name==='ws-toggle-task'){const t=workspaceData.tasks.find(t=>t.id===el.dataset.id);await api('/workspace/tasks/'+t.id,{method:'PATCH',body:{completed:!t.completed}});toast(t.completed?'Atividade reaberta.':'Atividade concluída.');render();return;}
 if(name==='ws-delete-task'){await api('/workspace/tasks/'+el.dataset.id,{method:'DELETE'});closeModal();toast('Atividade excluída.');render();return;}
 if(name==='ws-delete-note'){showModal('Excluir esta anotação?',`<p>A anotação será removida da sua conta.</p>`,button('Cancelar','close-modal','secondary')+`<button class="btn danger" data-action="ws-delete-note-confirm" data-id="${el.dataset.id}">Excluir anotação</button>`);return;}
 if(name==='ws-delete-note-confirm'){await api('/workspace/notes/'+el.dataset.id,{method:'DELETE'});try{localStorage.removeItem(noteDraftKey(el.dataset.id));}catch{}closeModal();toast('Anotação excluída.');go('/anotacoes');return;}
 if(name==='ws-note-review'){const item=workspaceData.reviewItems.find(i=>i.id===el.dataset.id);const values={title:'Revisão · '+item.subject,body:item.prompt+'\n\nMinha resposta: '+(item.answer===null||item.answer===''?'Não respondida':item.options[Number(item.answer)])+'\nResposta correta: '+item.options[Number(item.correct)]+'\n\n'+item.explanation+'\n\nO que quero lembrar na próxima tentativa:\n',prepId:item.prepId,favorite:false,sourceAttemptId:item.attemptId,sourceQuestionId:item.questionId};localStorage.setItem(noteDraftKey('new'),JSON.stringify({pending:true,values}));go('/anotacoes?nova=1');return;}
 if(name==='ws-review-toggle'){const item=workspaceData.reviewItems.find(i=>i.id===el.dataset.id);await api('/workspace/review',{method:'POST',body:{attemptId:item.attemptId,questionId:item.questionId,reviewed:!item.reviewedAt}});toast(item.reviewedAt?'Revisão reaberta.':'Questão marcada como revisada.');render();return;}
 if(name==='ws-review-task'){const item=workspaceData.reviewItems.find(i=>i.id===el.dataset.id);taskEditor();$('[name="title"]',$('.modal')).value='Revisar: '+item.subject;$('[name="kind"]',$('.modal')).value='review';$('[name="prepId"]',$('.modal')).value=item.prepId;$('#task-quiz-field').hidden=true;return;}
 if(name.startsWith('ws-focus-')){ensureFocus();if(name==='ws-focus-start'){if(!focusState.startedAt){const minutes=Number($('#f-focusMinutes').value);if(!Number.isInteger(minutes)||minutes<1||minutes>180)throw new Error('Escolha de 1 a 180 minutos.');focusState=defaultFocus(minutes,$('#f-focusTopic').value.trim().slice(0,160));focusState.startedAt=new Date().toISOString();focusState.eventId=crypto.randomUUID();}focusState.running=true;focusState.deadline=Date.now()+focusState.remainingMs;persistFocus();render();}else if(name==='ws-focus-pause'){pauseFocus();render();}else if(name==='ws-focus-reset'){if(focusState.startedAt){showModal('Reiniciar o bloco?','<p>O bloco atual será descartado. Para guardar o tempo, volte e use “Registrar tempo e encerrar”.</p>',button('Voltar','close-modal','secondary')+button('Descartar e reiniciar','ws-focus-reset-confirm'));}else{focusState=defaultFocus();persistFocus();render();}}else if(name==='ws-focus-reset-confirm'){focusState=defaultFocus();persistFocus();closeModal();render();}else if(name==='ws-focus-record'){pauseFocus();const minutes=Math.floor((focusState.minutes*60000-focusState.remainingMs)/60000);if(minutes<1)throw new Error('Complete pelo menos 1 minuto para registrar um bloco.');await api('/workspace/focus',{method:'POST',body:{eventId:focusState.eventId,minutes,topic:focusState.topic,startedAt:focusState.startedAt}});focusState=defaultFocus(focusState.minutes,focusState.topic);persistFocus();toast('Bloco registrado na sua conta.');render();}return;}
}
async function workspaceSubmit(form,values){
 const type=form.dataset.form;
 if(type==='workspace-note'){const id=form.dataset.noteId;values.favorite=!!$('[name="favorite"]',form).checked;values.sourceAttemptId=activeNote?.sourceAttemptId||null;values.sourceQuestionId=activeNote?.sourceQuestionId||null;const note=await api('/workspace/notes'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:values});try{localStorage.removeItem(noteDraftKey(id||'new'));}catch{}toast('Anotação salva na sua conta.');go('/anotacoes?nota='+note.id);}
 if(type==='workspace-task'){const id=form.dataset.id;await api('/workspace/tasks'+(id?'/'+id:''),{method:id?'PATCH':'POST',body:values});closeModal();toast('Atividade salva no seu plano.');render();}
 if(type==='workspace-goal'){await api('/workspace/preferences',{method:'PATCH',body:{...values,weeklyGoal:Number(values.weeklyGoal)}});closeModal();toast('Objetivo pessoal atualizado.');render();}
}
function contentChecklist(){return `<div class="admin-heading"><div><h2>Conteúdo para receber</h2><p>Estrutura preparada; exemplos demonstrativos não substituem um banco técnico revisado.</p></div></div><div class="card"><div class="card-header"><div><h3>O que existe hoje no catálogo</h3><p>Contagens de registros, não uma validação de cobertura do exame.</p></div>${badge('Demonstração')}</div><div class="table-wrap"><table><thead><tr><th>Preparação</th><th>Materiais</th><th>Questões</th><th>Simulados</th><th>Situação</th></tr></thead><tbody>${adminData.preparations.map(p=>`<tr><td>${E(p.name)}</td><td>${adminData.materials.filter(m=>m.prepId===p.id).length}</td><td>${adminData.questions.filter(q=>q.prepId===p.id).length}</td><td>${adminData.quizzes.filter(q=>q.prepId===p.id).length}</td><td>${badge(p.status==='published'?'Exemplo publicado localmente':'Em preparação','gray')}</td></tr>`).join('')}</tbody></table></div></div><div class="content-intake-grid"><section class="card"><h3>1. Provas e regras</h3><ul class="check-list">${['Nome completo da prova e da entidade responsável.','Link ou arquivo do edital/programa oficial e sua versão.','Quantidade de questões, alternativas e duração.','Nota mínima, mínimos por assunto e regras de pontuação.','Tipos de questão e regras de correção/revisão.'].map(s=>`<li>${icon('check',14)}${s}</li>`).join('')}</ul></section><section class="card"><h3>2. Matérias e materiais</h3><ul class="check-list">${['Lista de matérias, módulos e tópicos de cada prova.','Peso ou quantidade de questões por assunto, quando houver.','Textos, resumos e links autorizados para os materiais.','Fontes, versão/data e responsável pela revisão técnica.','Identificação do que já está revisado e do que é rascunho.'].map(s=>`<li>${icon('check',14)}${s}</li>`).join('')}</ul></section><section class="card"><h3>3. Banco de questões</h3><ul class="check-list">${['Enunciado e assunto de cada questão.','Alternativas e gabarito, nas objetivas.','Explicação comentada da resposta.','Rubrica, nota máxima e modelo de resposta, nas discursivas.','Origem e autorização de uso; diferenciar autoral de oficial.'].map(s=>`<li>${icon('check',14)}${s}</li>`).join('')}</ul></section><section class="card"><h3>4. Montagem dos simulados</h3><ul class="check-list">${['Nome e certificação de cada simulado.','Questões que entram em cada versão.','Tempo, pesos, critério de aprovação e limite de tentativas.','Quando liberar gabarito e explicações.','Quem vai corrigir discursivas e publicar os conteúdos.'].map(s=>`<li>${icon('check',14)}${s}</li>`).join('')}</ul></section></div><div class="card"><h3>Modelos para você me enviar</h3><p class="description">Você pode começar por uma única prova. Estes arquivos servem para organizar o envio; não são um importador automático.</p><div class="actions"><a class="btn secondary" href="./roteiro-conteudo.txt" download>Baixar roteiro de conteúdo ${icon('file',15)}</a><a class="btn secondary" href="./modelo-prova.json" download>Baixar modelo estruturado ${icon('arrow',15)}</a></div><p class="fine">O cadastro atual suporta texto e links HTTPS. PDFs, vídeos ou outros arquivos enviados precisam de tratamento e autorização antes de serem incorporados. Não há biblioteca de arquivos importada nesta prévia.</p></div>`;}

async function render(){const token=++renderId;try{if(!data)await refresh();const r=route(),base=r.parts[0]||'';document.title='Simulou Passou · '+({inicio:'Início',preparacoes:'Provas e certificações',materiais:'Materiais de apoio',simulados:'Simulados',desempenho:'Meu desempenho',admin:'Administração'}[base]||'Simulador de provas');let html;
 if(!base)html=landing();else if(['entrar','cadastro','recuperar','redefinir'].includes(base))html=authPage(base);else if(base==='checkout')html=await checkout();else {
 if(!data.user){go('/entrar');return;}let content,active=base,title=nav.find(([k])=>k===base)?.[2]||'Suas simulações';
 if(['inicio','anotacoes','plano','revisao','foco'].includes(base))workspaceData=await api('/workspace');
 if(!data.user.hasAccess&&!['inicio','anotacoes','plano','foco','conta','admin'].includes(base)){content=`<div class="card access-locked">${empty('Seu espaço está quase pronto.','O conteúdo fica disponível depois da confirmação do pagamento simulado.',link('Continuar para a compra','#/checkout','gold'))}</div>`;}
 else if(base==='inicio')content=home();else if(base==='preparacoes')content=preparations(r.query.get('prep')||'');else if(base==='materiais')content=materials(r.query.get('prep')||'');else if(base==='material'){const m=await api('/materials/'+r.parts[1]);content=reader(m);active='materiais';title='Material de apoio';}
 else if(base==='simulados')content=quizzes(r.query.get('prep')||'');else if(base==='simulado'){const q=data.quizzes.find(q=>q.id===r.parts[1]);content=q?quizStart(q):empty('Simulado não disponível.','Escolha outro simulado.',link('Ver simulados','#/simulados'));active='simulados';title='Antes de começar';}
 else if(base==='tentativa'){const a=await api('/attempts/'+r.parts[1]);if(currentAttempt?.id!==a.id)questionIndex=0;currentAttempt=a;if(a.status==='in_progress'){try{const draft=JSON.parse(localStorage.getItem(draftKey())||'null');if(draft?.pending){currentAttempt.answers=draft.answers;currentAttempt.flags=draft.flags;dirty=true;saveProblem=!navigator.onLine;setTimeout(saveDraft,100);}}catch{}content=attempt(currentAttempt);}else content=resultPage(a);active='simulados';title=a.status==='in_progress'?'Sua tentativa':'Resultado e revisão';}
 else if(base==='anotacoes')content=notesPage();else if(base==='plano')content=planPage();else if(base==='revisao')content=reviewPage();else if(base==='foco')content=focusPage();else if(base==='desempenho')content=performance(r.query.get('prep')||'');else if(base==='conta')content=account();else if(base==='admin'){if(data.user.role!=='master'){content=empty('Acesso restrito.','Esta área é exclusiva da administração.');}else{adminData=await api('/admin');content=admin(r.parts[1]||'visao-geral');}title='Administração';}else content=empty('Esta página não foi encontrada.','Volte para sua área de simulação.',link('Ir ao início','#/inicio'));
 html=shell(content,active,title);}
 if(token!==renderId)return;$('#app').innerHTML=html;updatePracticePlanner();window.scrollTo(0,0);tick();workspaceTick();syncWorkspaceMenu();
 }catch(e){if(token!==renderId)return;$('#app').innerHTML=data?.user?shell(errorPage(e),'','Tentar novamente'):bar()+`<main class="public-wrap section">${errorPage(e)}</main>`;}}
async function action(el){const name=el.dataset.action;if(name==='logout')pauseFocus();if(name.startsWith('ws-')){await workspaceAction(name,el);return;}if(name==='plan-preset'){$('#plan-sessions').value=el.dataset.count;updatePracticePlanner();return;}if(name==='close-modal'){closeModal();return;}if(name==='menu'){const menu=$('#sidebar');menu.classList.toggle('open');syncWorkspaceMenu();if(menu.classList.contains('open'))$('.sidebar-close')?.focus();else $('.app-header [data-action="menu"]')?.focus();return;}if(name==='retry'){await refresh();render();return;}if(name==='legal'&&data?.local===false){showModal(el.dataset.kind==='terms'?'Condições de uso · pré-lançamento':'Privacidade · pré-lançamento',cloudLegal(el.dataset.kind),button('Entendi','close-modal'));return;}if(name==='legal'){showModal(el.dataset.kind==='terms'?'Termos · prévia local':'Privacidade · prévia local',`<p>Este ambiente existe para validar a estrutura e não realiza vendas ou processamento por serviços externos.</p><p>Contas, tentativas e registros de teste ficam em um arquivo neste computador. Use dados fictícios. As senhas de cadastro local são armazenadas com derivação criptográfica, não em texto aberto.</p><p>Os textos legais de produção dependem da identificação real do responsável, canais de suporte, regras de cancelamento e reembolso e do tratamento de dados definido para o produto.</p>${notice('Este texto não substitui os termos e a política de privacidade que serão revisados antes da publicação.')}`,button('Entendi','close-modal'));return;}
 if(name==='demo-student'||name==='demo-master'){await api('/auth/demo',{method:'POST',body:{role:name==='demo-master'?'master':'student'}});await refresh();go(name==='demo-master'?'/admin':'/inicio');return;}
 if(name==='logout'){await api('/auth/logout',{method:'POST',body:{}});currentAttempt=null;data=null;await refresh();go('/');return;}
 if(name==='create-order'){await api('/orders',{method:'POST',body:{}});await refresh();render();return;}
 if(name==='confirm-payment'||name==='decline-payment'){const orders=await api('/orders'),o=orders.findLast(o=>o.status==='pending');if(!o)throw new Error('Inicie uma compra antes de confirmar.');await api('/orders/'+o.id+'/demo-event',{method:'POST',body:{status:name==='confirm-payment'?'paid':'declined',eventId:crypto.randomUUID()}});await refresh();toast(name==='confirm-payment'?'Pagamento simulado confirmado. Acesso liberado.':'Pagamento simulado recusado. O acesso continua bloqueado.');render();return;}
 if(name==='my-orders'){const orders=await api('/orders');showModal('Seus pagamentos locais',orders.length?orders.map(o=>`<div class="list-row"><div class="list-main"><h3>${money(o.amount)} · pagamento único</h3><p>${date(o.createdAt)} · Simulação local</p></div>${badge(o.status==='paid'?'Confirmado':o.status==='pending'?'Pendente':'Recusado',o.status==='paid'?'green':'')}</div>`).join(''):empty('Nenhum pagamento registrado.','Este perfil pode ter acesso de demonstração ou liberação manual.'),button('Fechar','close-modal'));return;}
 if(name==='complete-material'){const id=route().parts[1],completed=!data.completed.some(c=>c.materialId===id);await api('/materials/'+id+'/complete',{method:'POST',body:{completed}});await refresh();toast(completed?'Leitura marcada como concluída.':'Leitura marcada para retomar.');render();return;}
 if(name==='start-quiz'){const a=await api('/attempts',{method:'POST',body:{quizId:route().parts[1]}});currentAttempt=null;await refresh();go('/tentativa/'+a.id);return;}
 if(['previous-question','next-question','jump-question','flag'].includes(name)){if(name==='flag'){const id=currentAttempt.questions[questionIndex].id;currentAttempt.flags=currentAttempt.flags.includes(id)?currentAttempt.flags.filter(x=>x!==id):[...currentAttempt.flags,id];setDraft();}else questionIndex=name==='jump-question'?Number(el.dataset.index):questionIndex+(name==='next-question'?1:-1);const content=attempt(currentAttempt);$('#app').innerHTML=shell(content,'simulados','Sua tentativa');tick();if(name!=='flag')$('.question-prompt')?.scrollIntoView({block:'nearest'});return;}
 if(name==='ask-finish'){const blank=currentAttempt.questions.filter(q=>!String(currentAttempt.answers[q.id]||'').trim()).length;showModal('Vamos finalizar esta tentativa?',`<p>${blank?`Você ainda tem <strong>${blank} questão(ões) sem resposta</strong>. Pode voltar para responder ou concluir mesmo assim.`:'Todas as questões têm uma resposta. Você pode revisar antes de concluir.'}</p><p>Questões objetivas em branco contam no total aplicado. Discursivas respondidas serão encaminhadas para correção manual.</p><div id="finish-error" class="form-error" role="alert"></div>`,button('Voltar e revisar','close-modal','secondary')+button('Finalizar tentativa','finish-attempt'));return;}
 if(name==='finish-attempt'){await finishAttempt();return;}
 if(name==='edit-item'){editor(el.dataset.type,el.dataset.id);return;}
 if(name==='toggle-publish'){const type=el.dataset.type,item=adminData[type].find(x=>x.id===el.dataset.id);await api('/admin/'+type+'/'+item.id,{method:'PATCH',body:{status:item.status==='published'?'draft':'published'}});await refresh();toast('Situação atualizada.');render();return;}
 if(name==='toggle-access'){await api('/admin/access/'+el.dataset.id,{method:'PATCH',body:{active:el.dataset.active==='true'}});toast('Liberação manual atualizada.');render();}
}
async function finishAttempt(){if(finishBusy)return;finishBusy=true;try{clearTimeout(saveTimer);while(saving)await new Promise(r=>setTimeout(r,80));if(dirty)await saveDraft();if(dirty||saveProblem)throw new Error('Aguarde a conexão com o servidor para salvar suas respostas antes de finalizar.');const a=await api('/attempts/'+currentAttempt.id+'/finish',{method:'POST',body:{}});try{localStorage.removeItem(draftKey());}catch{}currentAttempt=a;closeModal();await refresh();render();}catch(e){if($('#finish-error'))$('#finish-error').textContent=e.message;else toast(e.message);}finally{finishBusy=false;}}
function tick(){const el=$('#timer');if(!el||!currentAttempt||currentAttempt.status!=='in_progress')return;const a=currentAttempt;const seconds=Math.max(0,a.deadline?Math.ceil((Date.parse(a.deadline)-Date.now())/1000):Math.floor((Date.now()-Date.parse(a.startedAt))/1000));el.textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(a.deadline&&seconds===0&&!finishBusy){finishAttempt();}if(saveProblem)updateSaveState('Rascunho neste navegador · reconecte para sincronizar');}
setInterval(tick,1000);
document.addEventListener('click',async event=>{const scroll=event.target.closest('[data-scroll]');if(scroll){event.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;el.disabled=true;try{await action(el);}catch(e){toast(e.message);}finally{if(el.isConnected)el.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const submit=$('[type="submit"]',form);if(submit?.disabled)return;const error=$('.form-error',form);if(error)error.textContent='';if(submit)submit.disabled=true;const values=Object.fromEntries(new FormData(form));try{const type=form.dataset.form;
 if(type.startsWith('workspace-')){await workspaceSubmit(form,values);return;}
 if(type==='register'||type==='login'){const result=await api('/auth/'+type,{method:'POST',body:values});if(result.confirmationRequired){$('#recovery-result').innerHTML=notice(E(result.message));form.reset();return;}await refresh();go('/inicio');}
 else if(type==='recover'){const d=await api('/auth/recover',{method:'POST',body:values});$('#recovery-result').innerHTML=notice(E(d.message)+(d.resetPath?`<br><a class="btn secondary compact" style="margin-top:12px" href="${E(d.resetPath)}">Abrir recuperação local</a>`:''));}
 else if(type==='reset'){await api('/auth/reset',{method:'POST',body:{...values,token:route().query.get('token')}});toast('Senha alterada. Entre novamente.');go('/entrar');}
 else if(type==='profile'){await api('/me',{method:'PATCH',body:values});await refresh();toast('Seu nome foi atualizado.');render();}
 else if(type==='admin-editor'){const collection=form.dataset.type;if(collection==='questions'){values.options=(values.options||'').split('\n').map(v=>v.trim()).filter(Boolean);values.correct=String(Number(values.correct)-1);values.points=Number(values.points);}if(collection==='quizzes'){values.questionIds=new FormData(form).getAll('questionIds');values.review=values.review==='true';}await api('/admin/'+collection+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PATCH':'POST',body:values});closeModal();await refresh();toast('Conteúdo salvo.');render();}
 else if(type==='grade'){await api('/admin/grade',{method:'POST',body:{...values,points:Number(values.points),attemptId:form.dataset.attempt,questionId:form.dataset.question}});await refresh();toast('Correção salva. O resultado do aluno foi atualizado.');render();}
 }catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-filter="prep"]')){go('/'+route().parts[0]+(el.value?'?prep='+encodeURIComponent(el.value):''));return;}if(el.name==='answer'&&currentAttempt){currentAttempt.answers[currentAttempt.questions[questionIndex].id]=el.value;setDraft();const map=$(`[data-action="jump-question"][data-index="${questionIndex}"]`);map?.classList.add('answered');}if(el.name==='type'&&el.closest('[data-form="admin-editor"]')){$('#objective-fields').hidden=el.value==='essay';$('#essay-fields').hidden=el.value!=='essay';}if(el.name==='prepId'&&el.closest('[data-type="quizzes"]'))$('#question-pick').innerHTML=questionPick(el.value);});
document.addEventListener('input',event=>{if(event.target.id==='essay-answer'&&currentAttempt){currentAttempt.answers[currentAttempt.questions[questionIndex].id]=event.target.value;setDraft();const map=$(`[data-action="jump-question"][data-index="${questionIndex}"]`);map?.classList.toggle('answered',!!event.target.value.trim());}});
document.addEventListener('keydown',event=>{const modal=$('.modal');if(!modal)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const f=[...modal.querySelectorAll('button,a[href],input,textarea,select')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=f[0],last=f.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();render();});
window.addEventListener('online',()=>{saveProblem=false;saveDraft();});
window.addEventListener('beforeunload',()=>{if(dirty&&currentAttempt)try{localStorage.setItem(draftKey(),JSON.stringify({answers:currentAttempt.answers,flags:currentAttempt.flags,pending:true}));}catch{}});
async function boot(){const tokens=new URLSearchParams(location.hash.slice(1));if(tokens.get('access_token')&&tokens.get('refresh_token')){const body={access_token:tokens.get('access_token'),refresh_token:tokens.get('refresh_token')},target=tokens.get('type')==='recovery'?'#/redefinir':'#/inicio';history.replaceState(null,'',location.pathname+location.search+target);try{await api('/auth/callback',{method:'POST',body});}catch{history.replaceState(null,'',location.pathname+location.search+'#/entrar');toast('O link expirou. Solicite outro link de recuperação.');}}await render();}
boot();

document.addEventListener('input',event=>{if(event.target.matches('[data-plan]'))updatePracticePlanner();});
document.addEventListener('change',event=>{if(event.target.id==='plan-quiz'){const quiz=data.quizzes.find(q=>q.id===event.target.value);if(quiz){$('#plan-questions').value=quiz.count;if(quiz.durationMinutes)$('#plan-minutes').value=quiz.durationMinutes;}updatePracticePlanner();}});

setInterval(workspaceTick,1000);
document.addEventListener('input',event=>{
 if(event.target.matches('[data-note-input]'))saveLocalNoteDraft();
 if(event.target.id==='note-search'){const term=event.target.value.trim().toLocaleLowerCase('pt-BR');for(const item of document.querySelectorAll('[data-note-search]'))item.hidden=!item.dataset.noteSearch.includes(term);}
});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.closest('[data-form="workspace-note"]'))saveLocalNoteDraft();
 if(el.id==='review-status'){const prep=route().query.get('prep');go('/revisao?situacao='+el.value+(prep?'&prep='+encodeURIComponent(prep):''));}
 const form=el.closest('[data-form="workspace-task"]');
 if(form&&el.name==='kind')$('#task-quiz-field').hidden=el.value!=='simulation';
 if(form&&el.name==='prepId'){const options=data.quizzes.filter(q=>!el.value||q.prepId===el.value);$('[name="quizId"]',form).innerHTML='<option value="">Escolher depois</option>'+options.map(q=>`<option value="${q.id}">${E(q.name)}</option>`).join('');}
});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&$('[data-form="workspace-note"]')){event.preventDefault();$('[data-form="workspace-note"]').requestSubmit();}});

function syncWorkspaceMenu(){const menu=$('#sidebar');if(!menu){document.body.classList.remove('workspace-menu-open');return;}const mobile=matchMedia('(max-width:860px)').matches;menu.inert=mobile&&!menu.classList.contains('open');const trigger=$('.app-header [data-action="menu"]');if(trigger)trigger.setAttribute('aria-expanded',String(mobile&&menu.classList.contains('open')));document.body.classList.toggle('workspace-menu-open',mobile&&menu.classList.contains('open'));}
window.addEventListener('resize',syncWorkspaceMenu);
document.addEventListener('keydown',event=>{const menu=$('#sidebar.open');if(!menu||!matchMedia('(max-width:860px)').matches||$('.modal'))return;if(event.key==='Escape'){menu.classList.remove('open');syncWorkspaceMenu();$('.app-header [data-action="menu"]')?.focus();return;}if(event.key==='Tab'){const list=[...menu.querySelectorAll('a,button')].filter(el=>el.offsetParent!==null&&!el.disabled);if(event.shiftKey&&document.activeElement===list[0]){event.preventDefault();list.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===list.at(-1)){event.preventDefault();list[0]?.focus();}}});
